static inline bool Clay__Array_RangeCheck(int32_t index, int32_t length)
{
    if (index < length && index >= 0) {
        return true;
    }
    Clay__Array_ReportOutOfBounds();
    return false;
}

static inline bool Clay__Array_AddCapacityCheck(int32_t length, int32_t capacity)
{
    if (length < capacity) {
        return true;
    }
    Clay__Array_ReportOutOfBounds();
    return false;
}

