#define RCI_TEXTSEL_MAGIC      0xA57u
#define RCI_TEXTSEL_MODE_BITS  2
#define RCI_TEXTSEL_ORD_BITS   18
#define RCI_TEXTSEL_ORD_MAX    ((1u << RCI_TEXTSEL_ORD_BITS) - 1u)

#define RCI_TEXTSEL_PACK(mode, ord) \
    ((uint32_t)((RCI_TEXTSEL_MAGIC << (RCI_TEXTSEL_MODE_BITS + RCI_TEXTSEL_ORD_BITS)) \
              | (((uint32_t)(ord) & RCI_TEXTSEL_ORD_MAX) << RCI_TEXTSEL_MODE_BITS) \
              | ((uint32_t)(mode) & 0x3u)))
#define RCI_TEXTSEL_HAS_MAGIC(tag) \
    ((((uint32_t)(tag)) >> (RCI_TEXTSEL_MODE_BITS + RCI_TEXTSEL_ORD_BITS)) == RCI_TEXTSEL_MAGIC)
#define RCI_TEXTSEL_MODE(tag)  ((uint32_t)(tag) & 0x3u)
#define RCI_TEXTSEL_ORD(tag)   ((((uint32_t)(tag)) >> RCI_TEXTSEL_MODE_BITS) & RCI_TEXTSEL_ORD_MAX)

