#define RCI_LOG_WARN_ONCE(...)                                 \
    do {                                                       \
        static int rci_log_warned_once = 0;                    \
        if (!rci_log_warned_once) {                            \
            rci_log_warned_once = 1;                           \
            rci_core_log(RC_LOG_WARNING, __VA_ARGS__);         \
        }                                                      \
    } while (0)

