static RC_LogCallback rci_core_log_sink      = NULL;
static void    *rci_core_log_sink_user = NULL;

void rcSetLogSink(RC_LogCallback sink, void *user) {
    rci_core_log_sink      = sink;
    rci_core_log_sink_user = user;
}

static const char *rci_core_log_tag(int level) {
    return level >= RC_LOG_ERROR   ? "ERROR"
         : level == RC_LOG_WARNING ? "WARNING"
                                   : "INFO";
}

static void rci_core_vlog(int level, const char *fmt, va_list args) {
    if (rci_core_log_sink) {

        char buf[512];
        vsnprintf(buf, sizeof buf, fmt, args);
        rci_core_log_sink((RC_LogLevel)level, buf, rci_core_log_sink_user);
        return;
    }
    const char *tag = rci_core_log_tag(level);
#ifdef __EMSCRIPTEN__

    {
        char line[512];
        int  n = snprintf(line, sizeof line, "RAYCLAY[%s]: ", tag);
        if (n < 0) {
            n = 0;
        }
        if ((size_t)n < sizeof line) {
            vsnprintf(line + n, sizeof line - (size_t)n, fmt, args);
        }
        if (level >= RC_LOG_ERROR) {
            emscripten_console_error(line);
        } else if (level == RC_LOG_WARNING) {
            emscripten_console_warn(line);
        } else {
            emscripten_console_log(line);
        }
    }
#else
    fprintf(stderr, "RAYCLAY[%s]: ", tag);
    vfprintf(stderr, fmt, args);
    fputc('\n', stderr);
#endif
}

void rci_core_log(int level, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    rci_core_vlog(level, fmt, args);
    va_end(args);
}

void rci_core_log_past_sink(int level, int pastSink, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    rci_core_vlog(level, fmt, args);
    va_end(args);
#ifdef __EMSCRIPTEN__

    (void)pastSink;
#else

    if (!pastSink || !rci_core_log_sink) {
        return;
    }
    fprintf(stderr, "RAYCLAY[%s]: ", rci_core_log_tag(level));
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fputc('\n', stderr);
#endif
}

Clay_String rcStringFromCStr(const char *cstr) {
    Clay_String s = {0};
    if (!cstr) { s.chars = ""; return s; }
    size_t len = strlen(cstr);
    if (len > (size_t)INT32_MAX) len = (size_t)INT32_MAX;
    s.length = (int32_t)len;
    s.chars  = cstr;
    return s;
}

#define RCI_ARENA_ALIGN (2 * sizeof(void *))

RC_Arena rcArenaInit(size_t size) {
    RC_Arena a = {0};
    a.buffer       = (unsigned char *)malloc(size);
    a.bufferLength = a.buffer ? size : 0;
    return a;
}

void *rcArenaAlloc(RC_Arena *arena, size_t size) {
    if (!arena || !arena->buffer || size == 0) return NULL;
    uintptr_t curPtr  = (uintptr_t)arena->buffer + (uintptr_t)arena->currOffset;
    uintptr_t mod     = curPtr & (uintptr_t)(RCI_ARENA_ALIGN - 1);
    uintptr_t aligned = mod ? (curPtr + RCI_ARENA_ALIGN - mod) : curPtr;
    size_t    offset  = (size_t)(aligned - (uintptr_t)arena->buffer);

    if (offset > arena->bufferLength || size > arena->bufferLength - offset)
        return NULL;
    arena->currOffset = offset + size;
    return arena->buffer + offset;
}

void rcArenaReset(RC_Arena *arena) {
    if (arena) arena->currOffset = 0;
}

void rcArenaFree(RC_Arena *arena) {
    if (!arena) return;
    free(arena->buffer);
    arena->buffer       = NULL;
    arena->bufferLength = 0;
    arena->currOffset   = 0;
}

Clay_String rcFormat(RC_Arena *arena, const char *format, ...) {
    if (!arena || !format) {
        Clay_String s = {0};
        s.chars = "";
        return s;
    }

    char stack[256];
    va_list args;
    va_start(args, format);
    int needed = vsnprintf(stack, sizeof stack, format, args);
    va_end(args);
    if (needed < 0) {
        Clay_String s = {0};
        s.chars = "";
        return s;
    }

    char *buf = (char *)rcArenaAlloc(arena, (size_t)needed + 1);
    if (!buf) {

        if (!arena->buffer || arena->bufferLength == 0) {
            RCI_LOG_WARN_ONCE(
                    "rcFormat: the arena passed in has no storage (%zu bytes "
                    "needed); returning a placeholder - set "
                    "RC_AppOptions.scratchArenaBytes if this is the runner's "
                    "scratch arena, or rcArenaInit your own",
                    (size_t)needed + 1);
            return rcStringFromCStr("<set scratchArenaBytes>");
        }
        RCI_LOG_WARN_ONCE(
                "rcFormat: the arena passed in is full (need %zu bytes, %zu cap); "
                "returning \"\" - raise RC_AppOptions.scratchArenaBytes if this is "
                "the runner's scratch arena, or the size given to rcArenaInit for "
                "your own", (size_t)needed + 1, arena->bufferLength);
        Clay_String s = {0};
        s.chars = "";
        return s;
    }

    if ((size_t)needed < sizeof stack) {
        memcpy(buf, stack, (size_t)needed + 1);
    } else {
        va_start(args, format);
        vsnprintf(buf, (size_t)needed + 1, format, args);
        va_end(args);
    }

    Clay_String s = {0};
    s.length = needed;
    s.chars  = buf;
    return s;
}

#define RCI_SIZING_FIT_ZERO  { { { 0.0f, 0.0f } }, CLAY__SIZING_TYPE_FIT }
#define RCI_SIZING_GROW_ZERO { { { 0.0f, 0.0f } }, CLAY__SIZING_TYPE_GROW }

