void rci_class_set_viewport(RC_Breakpoint bp) {
    rci_class_band = (unsigned)bp <= RC_BP_2XL ? (uint8_t)bp : RC_BP_BASE;

    rci_class_band_owned = true;
}

static void rci_class_band_sync(void) {
    float w;

    if (rci_class_band_owned) return;
    w = rci_core_layout_width();
    if (w == rci_class_band_width) return;
    rci_class_band_width = w;
    rci_class_band = (uint8_t)rci_viewport_breakpoint(w);
}

