#ifndef RC_GFX_DIGEST_H
#define RC_GFX_DIGEST_H

#include <stdint.h>
#include <string.h>
#include <stddef.h>

#ifndef RC_GFX_DIGEST
#define RC_GFX_DIGEST 0
#endif

#if !RC_GFX_DIGEST

#define rci_gfx_digest_reset(h)              ((void)0)
#define rci_gfx_digest_bytes(h, p, n)        ((void)0)
#define rci_gfx_digest_u32(h, v)             ((void)0)
#define rci_gfx_digest_f32(h, v)             ((void)0)
#define rci_gfx_digest_color(h, r, g, b, a)  ((void)0)
#define rci_gfx_digest_rect(h, x, y, w, ht)  ((void)0)

#else

#define RCI_FNV64_OFFSET 1469598103934665603ULL
#define RCI_FNV64_PRIME  1099511628211ULL

static inline void rci_gfx_digest_reset(uint64_t *h) {
    *h = RCI_FNV64_OFFSET;
}

static inline void rci_gfx_digest_bytes(uint64_t *h, const void *p, size_t n) {
    const unsigned char *b = (const unsigned char *)p;
    uint64_t acc = *h;
    size_t i;

    for (i = 0; i < n; i++) {
        acc ^= b[i];
        acc *= RCI_FNV64_PRIME;
    }
    *h = acc;
}

static inline void rci_gfx_digest_u32(uint64_t *h, uint32_t v) {
    rci_gfx_digest_bytes(h, &v, sizeof v);
}

static inline void rci_gfx_digest_f32(uint64_t *h, float f) {
    uint32_t u;

    if (f == 0.0f)
        f = 0.0f;
    if (f != f)
        u = 0x7fc00000u;
    else
        memcpy(&u, &f, sizeof u);
    rci_gfx_digest_u32(h, u);
}

static inline void rci_gfx_digest_color(uint64_t *h, float r, float g, float b, float a) {
    rci_gfx_digest_f32(h, r);
    rci_gfx_digest_f32(h, g);
    rci_gfx_digest_f32(h, b);
    rci_gfx_digest_f32(h, a);
}

static inline void rci_gfx_digest_rect(uint64_t *h, float x, float y, float w, float ht) {
    rci_gfx_digest_f32(h, x);
    rci_gfx_digest_f32(h, y);
    rci_gfx_digest_f32(h, w);
    rci_gfx_digest_f32(h, ht);
}

#endif

#endif

