int rci_font_utf8_decode(const char *s, const char *end, unsigned int *cp);

static inline int rci_font_utf8_decode_one(const char *s, const char *end,
                                           unsigned int *cp) {
    unsigned char c0 = (unsigned char)s[0];
    int           n;
    unsigned int  u;

    if (c0 < 0x80u) { *cp = c0; return 1; }
    if      (c0 >= 0xF0u && c0 <= 0xF4u) { n = 4; u = c0 & 0x07u; }
    else if (c0 >= 0xE0u)                { n = 3; u = c0 & 0x0Fu; }
    else if (c0 >= 0xC0u)                { n = 2; u = c0 & 0x1Fu; }
    else { *cp = c0; return 1; }

    if (n > end - s) { *cp = c0; return 1; }
    for (int i = 1; i < n; ++i) {
        unsigned char ci = (unsigned char)s[i];
        if ((ci & 0xC0u) != 0x80u) { *cp = c0; return 1; }
        u = (u << 6) | (ci & 0x3Fu);
    }
    *cp = u;
    return n;
}

static inline int rci_font_utf8_copy_bounded(char *dst, int cap,
                                             const char *b, const char *e,
                                             int *want)
{
    int n = 0;

    if (want) *want = (int)(e - b);
    if (cap <= 0) return 0;

    while (b < e) {
        unsigned int cp  = 0;
        int          adv = rci_font_utf8_decode_one(b, e, &cp);

        if (n + adv > cap - 1) break;
        for (int k = 0; k < adv; ++k) dst[n++] = b[k];
        b += adv;
    }
    dst[n] = '\0';
    return n;
}

