#ifndef RC_MAX_FONTS
#define RC_MAX_FONTS 16
#endif

#define RCI_FIRST_CHAR        32
#define RCI_ASCII_COUNT       95
#define RCI_ASCII_LAST        (RCI_FIRST_CHAR + RCI_ASCII_COUNT - 1)
#define RCI_LATIN1_FIRST      160
#define RCI_LAST_CHAR         RC_FONT_LAST_CODEPOINT
#define RCI_LATIN1_COUNT      (RCI_LAST_CHAR + 1 - RCI_LATIN1_FIRST)
#define RCI_GLYPH_COUNT       (RCI_LAST_CHAR + 1 - RCI_FIRST_CHAR)

#if RC_FONT_LAST_CODEPOINT < 160
#  error "RC_FONT_LAST_CODEPOINT must be >= 160. The glyph table is direct-indexed from 32 to the cap and the Latin-1 supplement begins at 160, so a lower cap cannot be expressed. ASCII-only is not available through this knob: printable ASCII 32..126 is always baked, and lowering the cap would not remove it."
#  undef  RCI_LAST_CHAR
#  define RCI_LAST_CHAR RCI_LATIN1_FIRST
#elif RC_FONT_LAST_CODEPOINT > 0x10FFFF
#  error "RC_FONT_LAST_CODEPOINT must be <= 0x10FFFF, the last Unicode code point. Note the cost is LINEAR IN THE CAP, not in what you draw - see rayclay.h."
#  undef  RCI_LAST_CHAR
#  define RCI_LAST_CHAR RCI_LATIN1_FIRST
#endif
#define RCI_DEFAULT_FONT_SIZE 16.0f

#define RCI_OVERSAMPLE_MAX_PX 36.0f

#define RCI_EFF_FIT_STEPS     6

#define RCI_ATLAS_W    RC_FONT_ATLAS_W
#define RCI_ATLAS_H    RC_FONT_ATLAS_H

#define RCI_GLYPH_WORDS ((RCI_GLYPH_COUNT + 31) / 32)

static bool rci_font_bit_get(const uint32_t *bits, int i) {
    return (bits[i >> 5] >> (i & 31)) & 1u;
}
static void rci_font_bit_set(uint32_t *bits, int i) {
    bits[i >> 5] |= 1u << (i & 31);
}

#define RCI_FONT_QUARANTINE_MAX 64

typedef struct {
    uint16_t gid[RCI_FONT_QUARANTINE_MAX];
    int      count;
} RCI_FontQuarantine;

static bool rci_font_quarantined(const RCI_FontQuarantine *q, int gid) {
    for (int i = 0; i < q->count; i++) {
        if (q->gid[i] == (uint16_t)gid)
            return true;
    }
    return false;
}

static int rci_font_pack_codepoint(bool symbol_shift, int cp) {
    return (symbol_shift && cp < 0x100) ? (0xF000 | (cp & 0xFF)) : cp;
}

typedef struct {
    stbtt_packedchar chars[RCI_GLYPH_COUNT];

    uint32_t         want[RCI_GLYPH_WORDS];
    uint32_t         baked[RCI_GLYPH_WORDS];

    uint32_t         blocked[RCI_GLYPH_WORDS];

    uint32_t         refused[RCI_GLYPH_WORDS];

    bool             symbolShift;

    bool             facePropsLogged;
    bool             osDowngradeLogged;
    unsigned         osH, osV;
    float            authoredSize;
    float            bakeSize;
    float            ascent;
    float            descent;
    float            lineGap;
    bool             loaded;

    const unsigned char *ttf;
    long                 ttfLen;
    bool                 ttfOwned;
} RCI_FontSlot;

static struct {
    unsigned char    *bitmap;
    stbtt_pack_context pc;
    bool              packing;
    RCI_FontSlot      slots[RC_MAX_FONTS];
    int               count;
    bool              dirty;
    bool              frozen;

    bool              staleRects;
} rci_font_f;

static uint32_t rci_font_atlas_gen = 1;

static void rci_font_atlas_touched(void) {
    rci_font_f.dirty = true;
    rci_font_atlas_gen++;
}

static float rci_font_oversample = 0.0f;

void rci_font_set_oversample(float oversample) {
    rci_font_oversample = oversample;
}

static float rci_font_eff_scale = 1.0f;

static bool rci_font_eff_held = false;

void rci_font_init(void) {
    if (rci_font_f.bitmap) return;
    rci_font_f.bitmap = (unsigned char *)calloc((size_t)RCI_ATLAS_W * RCI_ATLAS_H, 1);
    if (!rci_font_f.bitmap) {
        rci_core_log(RC_LOG_ERROR,
                "rc_font: could not allocate the glyph atlas; no text will render");
        return;
    }
    if (!stbtt_PackBegin(&rci_font_f.pc, rci_font_f.bitmap, RCI_ATLAS_W, RCI_ATLAS_H,
                         0, 1, NULL)) {
        rci_core_log(RC_LOG_ERROR,
                "rc_font: could not start the glyph atlas packer; no text will render");
        free(rci_font_f.bitmap);
        rci_font_f.bitmap = NULL;
        return;
    }

    rci_font_f.packing  = true;
    rci_font_f.count    = 0;

    rci_font_atlas_touched();
}

void rci_font_shutdown(void) {
    if (rci_font_f.packing) { stbtt_PackEnd(&rci_font_f.pc); rci_font_f.packing = false; }
    for (int i = 0; i < rci_font_f.count; i++)
        if (rci_font_f.slots[i].ttfOwned) free((void *)rci_font_f.slots[i].ttf);
    free(rci_font_f.bitmap);
    rci_font_f.bitmap    = NULL;
    rci_font_f.count     = 0;
    rci_font_f.dirty     = false;
    rci_font_f.frozen    = false;
    rci_font_f.staleRects = false;
    rci_font_eff_scale   = 1.0f;
    rci_font_eff_held    = false;
    memset(rci_font_f.slots, 0, sizeof(rci_font_f.slots));
}

static unsigned char *rci_font_read_file(const char *path, long *outLen) {
    long n = 0;
    unsigned char *buf = rci_file_read(path, LONG_MAX, &n, NULL);
    if (!buf) return NULL;

    if (n < 12) { free(buf); return NULL; }
    *outLen = n;
    return buf;
}

static unsigned long rci_font_be32(const unsigned char *p) {
    return ((unsigned long)p[0] << 24) | ((unsigned long)p[1] << 16) |
           ((unsigned long)p[2] << 8)  |  (unsigned long)p[3];
}

static bool rci_font_sfnt_version_ok(const unsigned char *p) {
    return (p[0] == 0x31 && p[1] == 0 && p[2] == 0 && p[3] == 0)
        || (p[0] == 't' && p[1] == 'y' && p[2] == 'p' && p[3] == '1')
        || (p[0] == 'O' && p[1] == 'T' && p[2] == 'T' && p[3] == 'O')
        || (p[0] == 0 && p[1] == 1 && p[2] == 0 && p[3] == 0)
        || (p[0] == 't' && p[1] == 'r' && p[2] == 'u' && p[3] == 'e');
}

#define RCI_GLYF_MAX_COMPOSITE_DEPTH 8

#define RCI_GLYF_COMPOSITE_BUDGET 128

#define RCI_CMAP_GID_SCAN_BUDGET 65536UL

static bool rci_font_glyf_nesting_ok(const unsigned char *ttf, long glyf_off, long glyf_len,
                                const unsigned char *lo, unsigned i2l,
                                unsigned long num_glyphs, unsigned long gi, int depth,
                                unsigned long *budget) {
    if (depth > RCI_GLYF_MAX_COMPOSITE_DEPTH)
        return false;
    if (gi >= num_glyphs)
        return false;

    unsigned long o0, o1;
    if (i2l == 0) {
        o0 = (((unsigned long)lo[2 * gi]     << 8) | lo[2 * gi + 1]) * 2;
        o1 = (((unsigned long)lo[2 * gi + 2] << 8) | lo[2 * gi + 3]) * 2;
    } else {
        o0 = rci_font_be32(lo + 4 * gi);
        o1 = rci_font_be32(lo + 4 * gi + 4);
    }
    if (o1 == o0)
        return true;
    if (o0 + 10 > (unsigned long)glyf_len)
        return false;

    const unsigned char *g = ttf + glyf_off + o0;
    if ((int16_t)(((unsigned)g[0] << 8) | g[1]) >= 0)
        return true;

    unsigned long p   = o0 + 10;
    unsigned long end = (unsigned long)glyf_len;
    for (;;) {
        if (p + 4 > end)
            return false;
        if (*budget == 0)
            return false;
        --*budget;
        unsigned flags = ((unsigned)ttf[glyf_off + p] << 8) | ttf[glyf_off + p + 1];
        unsigned long child = ((unsigned long)ttf[glyf_off + p + 2] << 8) | ttf[glyf_off + p + 3];

        if (!(flags & 0x0002))
            return false;
        p += 4;
        p += (flags & 0x0001) ? 4 : 2;
        if      (flags & 0x0008) p += 2;
        else if (flags & 0x0040) p += 4;
        else if (flags & 0x0080) p += 8;
        if (p > end)
            return false;
        if (!rci_font_glyf_nesting_ok(ttf, glyf_off, glyf_len, lo, i2l, num_glyphs, child, depth + 1,
                                     budget))
            return false;
        if (!(flags & 0x0020))
            break;
    }
    return true;
}

static bool rci_font_glyf_points_fit(const unsigned char *p,
                                     const unsigned char *end,
                                     long npts, bool *last_on_curve) {
    long          i    = 0;
    unsigned long need = 0;
    unsigned      last = 0;

    while (i < npts) {
        unsigned flags, run = 1;
        if (p >= end)
            return false;
        flags = *p++;
        if (flags & 0x08) {
            if (p >= end)
                return false;
            run += *p++;
        }
        if ((long)run > npts - i)
            run = (unsigned)(npts - i);

        if (npts - 1 < i + (long)run)
            last = flags;
        need += (flags & 0x02) ? run : ((flags & 0x10) ? 0u : 2u * run);
        need += (flags & 0x04) ? run : ((flags & 0x20) ? 0u : 2u * run);
        i    += (long)run;
    }

    if ((unsigned long)(end - p) < need)
        return false;
    *last_on_curve = (last & 0x01) != 0;
    return true;
}

typedef struct RCI_FontCffIndex {
    size_t   off;
    size_t   dataBase;
    size_t   end;
    uint32_t count;
    unsigned offSize;
} RCI_FontCffIndex;

static uint32_t rci_font_cff_offset(const unsigned char *p, size_t at, unsigned sz) {
    uint32_t v = 0;
    for (unsigned k = 0; k < sz; ++k)
        v = (v << 8) | (uint32_t)p[at + k];
    return v;
}

static bool rci_font_cff_index(const unsigned char *p, size_t off, size_t end,
                               RCI_FontCffIndex *ix) {
    uint32_t count, prev, cur;
    unsigned off_size;
    size_t   arr, base;

    if (off > end || end - off < 2)
        return false;
    count = (uint32_t)(((unsigned)p[off] << 8) | p[off + 1]);
    if (count == 0) {
        ix->off      = off;
        ix->dataBase = off + 2;
        ix->end      = off + 2;
        ix->count    = 0;
        ix->offSize  = 0;
        return true;
    }
    if (end - off < 3)
        return false;
    off_size = p[off + 2];
    if (off_size < 1 || off_size > 4)
        return false;
    arr = off + 3;

    if ((size_t)(count + 1u) * off_size > end - arr)
        return false;
    base = arr + (size_t)(count + 1u) * off_size - 1u;
    prev = rci_font_cff_offset(p, arr, off_size);
    if (prev < 1)
        return false;
    for (uint32_t i = 1; i <= count; ++i) {
        cur = rci_font_cff_offset(p, arr + (size_t)i * off_size, off_size);
        if (cur < prev)
            return false;
        prev = cur;
    }

    if (base > end || (size_t)prev > end - base)
        return false;
    ix->off      = off;
    ix->dataBase = base;
    ix->end      = base + prev;
    ix->count    = count;
    ix->offSize  = off_size;
    return true;
}

static bool rci_font_cff_entry(const unsigned char *p, const RCI_FontCffIndex *ix,
                               uint32_t i, size_t *o0, size_t *o1) {
    uint32_t a, b;
    if (i >= ix->count)
        return false;
    a = rci_font_cff_offset(p, ix->off + 3 + (size_t)i * ix->offSize, ix->offSize);
    b = rci_font_cff_offset(p, ix->off + 3 + (size_t)(i + 1) * ix->offSize, ix->offSize);
    if (b < a)
        return false;
    *o0 = ix->dataBase + a;
    *o1 = ix->dataBase + b;
    return *o1 <= ix->end;
}

static int rci_font_cff_dict(const unsigned char *p, size_t off, size_t end,
                             unsigned op, int want, int32_t *out) {
    int32_t stack[48];
    int     sp = 0, n;
    size_t  i  = off;

    while (i < end) {
        unsigned b0 = p[i];
        if (b0 <= 21) {
            unsigned o = b0;
            ++i;
            if (b0 == 12) {
                if (i >= end)
                    return -1;
                o = 0x100u | (unsigned)p[i];
                ++i;
            }
            if (o == op) {
                n = sp < want ? sp : want;
                for (int k = 0; k < n; ++k)
                    out[k] = stack[k];
                return n;
            }
            sp = 0;
        } else if (b0 == 28) {
            if (end - i < 3 || sp >= 48)
                return -1;
            stack[sp++] = (int32_t)(int16_t)(((unsigned)p[i + 1] << 8) | p[i + 2]);
            i += 3;
        } else if (b0 == 29) {
            if (end - i < 5 || sp >= 48)
                return -1;
            stack[sp++] = (int32_t)(uint32_t)rci_font_be32(p + i + 1);
            i += 5;
        } else if (b0 == 30) {
            bool done = false;
            ++i;
            while (i < end && !done) {
                unsigned byte = p[i++];
                if ((byte >> 4) == 0xFu || (byte & 0xFu) == 0xFu)
                    done = true;
            }
            if (!done || sp >= 48)
                return -1;
            stack[sp++] = 0;
        } else if (b0 < 32 || b0 == 255) {

            return -1;
        } else if (b0 <= 246) {
            if (sp >= 48)
                return -1;
            stack[sp++] = (int32_t)b0 - 139;
            ++i;
        } else if (b0 <= 250) {
            if (end - i < 2 || sp >= 48)
                return -1;
            stack[sp++] = ((int32_t)b0 - 247) * 256 + (int32_t)p[i + 1] + 108;
            i += 2;
        } else if (b0 <= 254) {
            if (end - i < 2 || sp >= 48)
                return -1;
            stack[sp++] = -((int32_t)b0 - 251) * 256 - (int32_t)p[i + 1] - 108;
            i += 2;
        } else {
            return -1;
        }
    }
    return 0;
}

static bool rci_font_cff_private(const unsigned char *p, size_t cff, size_t end,
                                 int32_t psz, int32_t poff) {
    size_t  pstart, pend;
    int32_t subrs = 0;
    RCI_FontCffIndex ix;

    if (psz < 0 || poff < 0 || (size_t)poff > end - cff)
        return false;
    pstart = cff + (size_t)poff;
    if ((size_t)psz > end - pstart)
        return false;
    pend = pstart + (size_t)psz;
    if (rci_font_cff_dict(p, pstart, pend, 19u, 1, &subrs) < 0)
        return false;

    if (subrs < 0)
        return false;
    if (subrs != 0) {
        if ((size_t)subrs > end - pstart)
            return false;
        if (!rci_font_cff_index(p, pstart + (size_t)subrs, end, &ix))
            return false;
    }
    return true;
}

static bool rci_font_validate_cff(const unsigned char *p, size_t off, size_t tl,
                                  uint32_t num_glyphs) {
    size_t   end = off + tl, top0, top1;
    unsigned hdrsz;
    RCI_FontCffIndex name_ix, top_ix, str_ix, gsubr_ix, cs_ix, fd_ix;
    int32_t  v[2];
    int      n;

    if (tl < 4)
        return false;
    hdrsz = p[off + 2];
    if (hdrsz < 4 || (size_t)hdrsz > tl)
        return false;

    if (!rci_font_cff_index(p, off + hdrsz, end, &name_ix))
        return false;
    if (!rci_font_cff_index(p, name_ix.end, end, &top_ix))
        return false;
    if (top_ix.count < 1)
        return false;
    if (!rci_font_cff_index(p, top_ix.end, end, &str_ix))
        return false;
    if (!rci_font_cff_index(p, str_ix.end, end, &gsubr_ix))
        return false;
    if (!rci_font_cff_entry(p, &top_ix, 0, &top0, &top1))
        return false;

    n = rci_font_cff_dict(p, top0, top1, 0x100u | 6u, 1, v);
    if (n < 0 || (n == 1 && v[0] != 2))
        return false;

    n = rci_font_cff_dict(p, top0, top1, 17u, 1, v);
    if (n != 1 || v[0] < 0 || (size_t)v[0] > tl)
        return false;
    if (!rci_font_cff_index(p, off + (size_t)v[0], end, &cs_ix))
        return false;

    if (cs_ix.count != num_glyphs)
        return false;

    n = rci_font_cff_dict(p, top0, top1, 18u, 2, v);
    if (n < 0)
        return false;
    if (n == 2 && !rci_font_cff_private(p, off, end, v[0], v[1]))
        return false;

    {
        int32_t fdarray = 0, fdselect = 0;
        int     na = rci_font_cff_dict(p, top0, top1, 0x100u | 36u, 1, &fdarray);
        int     ns = rci_font_cff_dict(p, top0, top1, 0x100u | 37u, 1, &fdselect);
        if (na < 0 || ns < 0)
            return false;

        if ((na == 1 && fdarray < 0) || (ns == 1 && fdselect < 0))
            return false;
        if (na == 1 && fdarray != 0) {
            if (ns != 1 || fdselect <= 0 || (size_t)fdarray > tl)
                return false;
            if (!rci_font_cff_index(p, off + (size_t)fdarray, end, &fd_ix))
                return false;
            for (uint32_t k = 0; k < fd_ix.count; ++k) {
                size_t  f0, f1;
                int32_t pv[2];
                if (!rci_font_cff_entry(p, &fd_ix, k, &f0, &f1))
                    return false;
                n = rci_font_cff_dict(p, f0, f1, 18u, 2, pv);
                if (n < 0)
                    return false;
                if (n == 2 && !rci_font_cff_private(p, off, end, pv[0], pv[1]))
                    return false;
            }

            {
                size_t fs;
                if ((size_t)fdselect >= tl)
                    return false;
                fs = off + (size_t)fdselect;
                if (p[fs] == 0) {
                    if ((size_t)num_glyphs > end - fs - 1u)
                        return false;
                } else if (p[fs] == 3) {
                    uint32_t nr;
                    if (end - fs < 5u)
                        return false;
                    nr = (uint32_t)(((unsigned)p[fs + 1] << 8) | p[fs + 2]);

                    if ((size_t)nr * 3u + 5u > end - fs)
                        return false;
                } else {
                    return false;
                }
            }
        }
    }
    return true;
}

static long rci_font_validate(const unsigned char *ttf, long len,
                              RCI_FontQuarantine *q) {
    q->count = 0;
    if (len < 12)
        return -1;
    long fontstart = 0;

    if (ttf[0] == 't' && ttf[1] == 't' && ttf[2] == 'c' && ttf[3] == 'f') {
        if (len < 16)
            return -1;
        unsigned long ver = rci_font_be32(ttf + 4);
        if (ver != 0x00010000UL && ver != 0x00020000UL)
            return -1;
        if ((int32_t)(uint32_t)rci_font_be32(ttf + 8) < 1)
            return -1;
        fontstart = (long)rci_font_be32(ttf + 12);
    } else if (!rci_font_sfnt_version_ok(ttf)) {

        return -1;
    }
    if (fontstart < 0 || fontstart > len - 12)
        return -1;
    const unsigned char *base = ttf + fontstart;
    int num_tables = (base[4] << 8) | base[5];

    if ((long)num_tables > (len - fontstart - 12) / 16)
        return -1;

    long head_off = -1, hhea_off = -1, maxp_off = -1, loca_off = -1, loca_len = -1;

    long hmtx_off = -1, hmtx_len = -1;

    long     cmap_sel_abs = -1;
    unsigned cmap_sel_fmt = 0;
    long glyf_off = -1, glyf_len = -1;

    long cff_off = -1, cff_len = -1;

    for (int i = 0; i < num_tables; ++i) {
        const unsigned char *e   = base + 12 + 16 * i;
        unsigned long        off = rci_font_be32(e + 8);
        unsigned long        tl  = rci_font_be32(e + 12);
        if (off > (unsigned long)len || tl > (unsigned long)len - off)
            return -1;

        if (e[0] == 'h' && e[1] == 'e' && e[2] == 'a' && e[3] == 'd') {
            if (tl < 54)
                return -1;
            if (head_off < 0)
                head_off = (long)off;
        } else if (e[0] == 'h' && e[1] == 'h' && e[2] == 'e' && e[3] == 'a') {
            if (tl < 36)
                return -1;
            if (hhea_off < 0)
                hhea_off = (long)off;
        } else if (e[0] == 'm' && e[1] == 'a' && e[2] == 'x' && e[3] == 'p') {
            if (tl < 6)
                return -1;
            if (maxp_off < 0)
                maxp_off = (long)off;
        } else if (e[0] == 'l' && e[1] == 'o' && e[2] == 'c' && e[3] == 'a') {
            if (loca_off < 0) {
                loca_off = (long)off;
                loca_len = (long)tl;
            }
        } else if (e[0] == 'g' && e[1] == 'l' && e[2] == 'y' && e[3] == 'f') {
            if (glyf_off < 0) {
                glyf_off = (long)off;
                glyf_len = (long)tl;
            }
        } else if (e[0] == 'h' && e[1] == 'm' && e[2] == 't' && e[3] == 'x') {
            if (hmtx_off < 0) {
                hmtx_off = (long)off;
                hmtx_len = (long)tl;
            }
        } else if (e[0] == 'C' && e[1] == 'F' && e[2] == 'F' && e[3] == ' ') {
            if (cff_off < 0) {
                cff_off = (long)off;
                cff_len = (long)tl;
            }
        }

        if (e[0] == 'c' && e[1] == 'm' && e[2] == 'a' && e[3] == 'p') {
            if (tl < 4)
                return -1;
            unsigned long nsub = ((unsigned long)ttf[off + 2] << 8) | ttf[off + 3];
            if (4UL + 8UL * nsub > tl)
                return -1;

            bool          sel     = false;
            unsigned      sel_fmt = 0;
            unsigned long sel_so  = 0;

            bool          sym     = false;
            unsigned      sym_fmt = 0;
            unsigned long sym_so  = 0;
            for (unsigned long s = 0; s < nsub; ++s) {
                unsigned long so = rci_font_be32(ttf + off + 8 + 8 * s);
                if (so >= tl)
                    return -1;

                if (so + 2 > tl)
                    return -1;
                unsigned fmt  = ((unsigned)ttf[off + so] << 8) | ttf[off + so + 1];
                unsigned plat = ((unsigned)ttf[off + 4 + 8 * s] << 8) | ttf[off + 5 + 8 * s];
                unsigned enc  = ((unsigned)ttf[off + 6 + 8 * s] << 8) | ttf[off + 7 + 8 * s];
                if (plat == 0 || (plat == 3 && (enc == 1 || enc == 10))) {
                    sel = true; sel_fmt = fmt; sel_so = so;
                } else if (plat == 3 && enc == 0) {
                    sym = true; sym_fmt = fmt; sym_so = so;
                }
                if (fmt == 0) {
                    if (so + 4 > tl)
                        return -1;
                    unsigned long b = ((unsigned long)ttf[off + so + 2] << 8) | ttf[off + so + 3];
                    if (b > tl - so)
                        return -1;
                } else if (fmt == 6) {
                    if (so + 10 > tl)
                        return -1;
                    unsigned long cnt = ((unsigned long)ttf[off + so + 8] << 8) | ttf[off + so + 9];
                    if (cnt > (tl - so - 10) / 2)
                        return -1;
                } else if (fmt == 4) {
                    if (so + 16 > tl)
                        return -1;
                    unsigned long seg = (((unsigned long)ttf[off + so + 6] << 8) | ttf[off + so + 7]) >> 1;
                    if (seg > (tl - so - 16) / 8)
                        return -1;

                    const unsigned char *ec0 = ttf + off + so + 14;
                    const unsigned char *sc0 = ttf + off + so + 16 + 2 * seg;
                    const unsigned char *ir0 = ttf + off + so + 16 + 6 * seg;
                    for (unsigned long si = 0; si < seg; ++si) {
                        unsigned long iro = ((unsigned long)ir0[2 * si] << 8) | ir0[2 * si + 1];
                        if (iro == 0)
                            continue;
                        unsigned long ec = ((unsigned long)ec0[2 * si] << 8) | ec0[2 * si + 1];
                        unsigned long sc = ((unsigned long)sc0[2 * si] << 8) | sc0[2 * si + 1];
                        if (ec < sc)
                            continue;
                        unsigned long ro = 16 + 6 * seg + 2 * si + iro + 2 * (ec - sc);
                        if (ro + 2 > tl - so)
                            return -1;
                    }
                } else if (fmt == 12 || fmt == 13) {
                    if (so + 16 > tl)
                        return -1;
                    unsigned long ng = rci_font_be32(ttf + off + so + 12);
                    if (ng > (tl - so - 16) / 12)
                        return -1;
                }
            }

            if (!sel && sym) {
                sel = true; sel_fmt = sym_fmt; sel_so = sym_so;
            }

            if (sel) {
                if (sel_fmt != 0 && sel_fmt != 4 && sel_fmt != 6 &&
                    sel_fmt != 12 && sel_fmt != 13)
                    return -1;
                if (sel_fmt == 4) {
                    unsigned long sg = (((unsigned long)ttf[off + sel_so + 6] << 8)
                                        | ttf[off + sel_so + 7]) >> 1;

                    if (sg < 1)
                        return -1;
                    unsigned long p2 = 1, es = 0;
                    while (p2 * 2 <= sg) { p2 *= 2; ++es; }
                    unsigned long sr = 2 * p2;
                    if ((((unsigned long)ttf[off + sel_so + 8]  << 8) | ttf[off + sel_so + 9])  != sr         ||
                        (((unsigned long)ttf[off + sel_so + 10] << 8) | ttf[off + sel_so + 11]) != es         ||
                        (((unsigned long)ttf[off + sel_so + 12] << 8) | ttf[off + sel_so + 13]) != 2 * sg - sr)
                        return -1;
                }

                cmap_sel_abs = (long)(off + sel_so);
                cmap_sel_fmt = sel_fmt;
            }
        }
    }

    if (hhea_off < 0)
        return -1;
    {
        int asc  = (int16_t)(((unsigned)ttf[hhea_off + 4] << 8) | ttf[hhea_off + 5]);
        int desc = (int16_t)(((unsigned)ttf[hhea_off + 6] << 8) | ttf[hhea_off + 7]);
        if (asc - desc <= 0)
            return -1;
    }

    if ((((unsigned)ttf[hhea_off + 34] << 8) | ttf[hhea_off + 35]) == 0)
        return -1;

    if (hmtx_off >= 0 && maxp_off >= 0) {
        unsigned long nhm  = ((unsigned long)ttf[hhea_off + 34] << 8) | ttf[hhea_off + 35];
        unsigned long ng   = ((unsigned long)ttf[maxp_off + 4] << 8) | ttf[maxp_off + 5];
        unsigned long need = 4UL * nhm + (ng > nhm ? 2UL * (ng - nhm) : 0UL);
        if ((unsigned long)hmtx_len < need)
            return -1;
    }

    if (cmap_sel_abs >= 0 &&
        (cmap_sel_fmt == 0 || cmap_sel_fmt == 4 || cmap_sel_fmt == 6)) {
        if (maxp_off < 0)
            return -1;
        unsigned long ng = ((unsigned long)ttf[maxp_off + 4] << 8) | ttf[maxp_off + 5];
        const unsigned char *sub = ttf + cmap_sel_abs;
        if (cmap_sel_fmt == 0) {

            unsigned long n = ((unsigned long)sub[2] << 8) | sub[3];
            for (unsigned long i = 6; i < n; ++i)
                if ((unsigned long)sub[i] >= ng)
                    return -1;
        } else if (cmap_sel_fmt == 6) {
            unsigned long cnt = ((unsigned long)sub[8] << 8) | sub[9];
            for (unsigned long i = 0; i < cnt; ++i)
                if ((((unsigned long)sub[10 + 2 * i] << 8) | sub[11 + 2 * i]) >= ng)
                    return -1;
        } else {
            unsigned long seg    = (((unsigned long)sub[6] << 8) | sub[7]) >> 1;
            unsigned long budget = RCI_CMAP_GID_SCAN_BUDGET;
            for (unsigned long si = 0; si < seg; ++si) {
                unsigned long ec  = ((unsigned long)sub[14 + 2 * si] << 8) | sub[15 + 2 * si];
                unsigned long sc  = ((unsigned long)sub[16 + 2 * seg + 2 * si] << 8)
                                    | sub[17 + 2 * seg + 2 * si];
                unsigned long dl  = ((unsigned long)sub[16 + 4 * seg + 2 * si] << 8)
                                    | sub[17 + 4 * seg + 2 * si];
                unsigned long iro = ((unsigned long)sub[16 + 6 * seg + 2 * si] << 8)
                                    | sub[17 + 6 * seg + 2 * si];
                if (ec < sc)
                    continue;
                if (iro == 0) {

                    unsigned long g0 = (sc + dl) & 0xFFFFUL;
                    if (g0 + (ec - sc) >= ng)
                        return -1;
                } else {
                    const unsigned char *slot = sub + 16 + 6 * seg + 2 * si + iro;
                    if (ec - sc >= budget)
                        return -1;
                    budget -= ec - sc + 1;
                    for (unsigned long k = 0; k <= ec - sc; ++k)
                        if ((((unsigned long)slot[2 * k] << 8) | slot[2 * k + 1]) >= ng)
                            return -1;
                }
            }
        }
    }
    if (cmap_sel_abs >= 0 && (cmap_sel_fmt == 12 || cmap_sel_fmt == 13)) {
        if (maxp_off < 0)
            return -1;
        unsigned long ng     = ((unsigned long)ttf[maxp_off + 4] << 8) | ttf[maxp_off + 5];
        unsigned long groups = rci_font_be32(ttf + cmap_sel_abs + 12);
        for (unsigned long gi = 0; gi < groups; ++gi) {
            const unsigned char *grp = ttf + cmap_sel_abs + 16 + 12 * gi;
            unsigned long start_char = rci_font_be32(grp);
            unsigned long end_char   = rci_font_be32(grp + 4);
            unsigned long start_gid  = rci_font_be32(grp + 8);
            if (end_char < start_char || start_gid >= ng)
                return -1;
            if (cmap_sel_fmt == 12 && start_gid + (end_char - start_char) >= ng)
                return -1;
        }
    }

    if (glyf_off <= 0 && cff_off > 0) {
        if (maxp_off < 0)
            return -1;
        unsigned long num_glyphs = ((unsigned long)ttf[maxp_off + 4] << 8) | ttf[maxp_off + 5];
        if (!rci_font_validate_cff(ttf, (size_t)cff_off, (size_t)cff_len,
                                   (uint32_t)num_glyphs))
            return -1;
    }

    if (glyf_off >= 0) {

        if (loca_off < 0 || head_off < 0 || maxp_off < 0)
            return -1;
        unsigned long num_glyphs = ((unsigned long)ttf[maxp_off + 4] << 8) | ttf[maxp_off + 5];
        unsigned      i2l        = ((unsigned)ttf[head_off + 50] << 8) | ttf[head_off + 51];

        if (i2l < 2) {
            long entryw = i2l == 0 ? 2 : 4;
            if (loca_len < (long)((num_glyphs + 1) * (unsigned long)entryw))
                return -1;
            const unsigned char *lo = ttf + loca_off;

            unsigned long comp_budget = num_glyphs * (unsigned long)RCI_GLYF_COMPOSITE_BUDGET;
            for (unsigned long gi = 0; gi < num_glyphs; ++gi) {
                unsigned long o0, o1;
                if (i2l == 0) {
                    o0 = (((unsigned long)lo[2 * gi]     << 8) | lo[2 * gi + 1]) * 2;
                    o1 = (((unsigned long)lo[2 * gi + 2] << 8) | lo[2 * gi + 3]) * 2;
                } else {
                    o0 = rci_font_be32(lo + 4 * gi);
                    o1 = rci_font_be32(lo + 4 * gi + 4);
                }
                if (o1 == o0)
                    continue;
                if (o0 + 10 > (unsigned long)glyf_len)
                    return -1;

                {
                    const unsigned char *bb = ttf + glyf_off + o0;
                    int xmin = (int16_t)(((unsigned)bb[2] << 8) | bb[3]);
                    int ymin = (int16_t)(((unsigned)bb[4] << 8) | bb[5]);
                    int xmax = (int16_t)(((unsigned)bb[6] << 8) | bb[7]);
                    int ymax = (int16_t)(((unsigned)bb[8] << 8) | bb[9]);
                    int nc   = (int16_t)(((unsigned)bb[0] << 8) | bb[1]);
                    if (xmax < xmin || ymax < ymin)
                        return -1;

                    if (nc > 0) {
                        unsigned long need = o0 + 10 + (unsigned long)nc * 2 + 2;
                        if (need > (unsigned long)glyf_len)
                            return -1;
                        const unsigned char *il  = bb + 10 + (unsigned long)nc * 2;
                        unsigned long        ins = ((unsigned long)il[0] << 8) | il[1];
                        if (need + ins > (unsigned long)glyf_len)
                            return -1;

                        {
                            const unsigned char *ep = bb + 10;
                            long prev = -1;
                            bool one_point_last = false, last_on_curve = false;
                            for (int c = 0; c < nc; ++c) {
                                long e = (long)(((unsigned)ep[2 * c] << 8) | ep[2 * c + 1]);
                                if (e <= prev)
                                    return -1;
                                if (c == nc - 1)
                                    one_point_last = (e == prev + 1);
                                prev = e;
                            }
                            if (!rci_font_glyf_points_fit(
                                    il + 2 + ins, ttf + glyf_off + glyf_len,
                                    prev + 1, &last_on_curve))
                                return -1;

                            if (one_point_last && !last_on_curve) {
                                if (q->count >= RCI_FONT_QUARANTINE_MAX)
                                    return -1;
                                q->gid[q->count++] = (uint16_t)gi;
                            }
                        }
                    } else if (nc < 0 &&
                               !rci_font_glyf_nesting_ok(ttf, glyf_off, glyf_len, lo, i2l,
                                                    num_glyphs, gi, 1, &comp_budget)) {
                        return -1;
                    }
                }
            }
        }
    }
    return fontstart;
}

static void rci_font_oversample_for(float bakeSize, unsigned *h, unsigned *v) {
    if (rci_font_oversample > 0.0f) {

        float f = rci_font_oversample;
        if (f < 1.0f) f = 1.0f;
        if (f > 8.0f) f = 8.0f;
        *h = *v = (unsigned)(f + 0.5f);
        return;
    }
    *h = (bakeSize < RCI_OVERSAMPLE_MAX_PX) ? 2u : 1u;
    *v = 1u;
}

static bool rci_font_rebake_all(bool speculative);

static bool rci_font_pack_slot(RCI_FontSlot *slot, const unsigned char *ttf, long len,
                          float bakeSize, bool speculative) {
    stbtt_fontinfo info;

    RCI_FontQuarantine quarantine;
    long offset = rci_font_validate(ttf, len, &quarantine);
    if (offset < 0) {
        rci_core_log(RC_LOG_ERROR, "rc_font: bad font data");
        return false;
    }

    if (!stbtt_InitFont(&info, ttf, (int)offset)) {
        rci_core_log(RC_LOG_ERROR,
                "rc_font: unsupported font (structure is valid; this build's "
                "rasteriser cannot open it). Known causes: a font COLLECTION "
                "(.ttc/.otc), CFF2 outlines, or a symbol-only cmap. Supply a "
                "single-face .ttf or .otf instead.");
        return false;
    }

    const bool describeFace = !slot->facePropsLogged;
    slot->facePropsLogged = true;
    if (quarantine.count > 0 && describeFace)
        rci_core_log(RC_LOG_WARNING,
                "rc_font: %d glyph(s) skipped as unsafe to rasterise; the rest of "
                "the face loads normally",
                quarantine.count);

    unsigned h, v;
    rci_font_oversample_for(bakeSize, &h, &v);

    slot->osH = h;
    slot->osV = v;

    const unsigned reqH = h, reqV = v;

    {
        int plain = 0, shifted = 0;
        for (int cp = RCI_FIRST_CHAR; cp <= RCI_ASCII_LAST; cp++) {
            if (stbtt_FindGlyphIndex(&info, cp))
                plain++;
            if (stbtt_FindGlyphIndex(&info, 0xF000 | cp))
                shifted++;
        }
        slot->symbolShift = shifted > plain;
        if (slot->symbolShift && describeFace)
            rci_core_log(RC_LOG_WARNING,
                    "rc_font: symbol-encoded face (%d of %d ASCII glyphs live in the "
                    "private use area); characters map to symbols, not letters",
                    shifted, RCI_ASCII_COUNT);
    }

    const bool filtering = quarantine.count > 0;
    memset(slot->blocked, 0, sizeof(slot->blocked));
    if (filtering) {

        for (int g = 0; g < RCI_GLYPH_COUNT; g++) {
            int cp = rci_font_pack_codepoint(slot->symbolShift, g + RCI_FIRST_CHAR);
            if (rci_font_quarantined(&quarantine, stbtt_FindGlyphIndex(&info, cp)))
                rci_font_bit_set(slot->blocked, g);
        }
    }

    int              asciiCp[RCI_ASCII_COUNT], asciiG[RCI_ASCII_COUNT];
    stbtt_packedchar asciiOut[RCI_ASCII_COUNT];
    int              nAscii = 0;
    if (filtering) {
        for (int i = 0; i < RCI_ASCII_COUNT; i++) {
            if (rci_font_bit_get(slot->blocked, i))
                continue;
            asciiG[nAscii]    = i;
            asciiCp[nAscii++] = rci_font_pack_codepoint(slot->symbolShift,
                                                        RCI_FIRST_CHAR + i);
        }
    }

    int              extraCp[RCI_LATIN1_COUNT], extraG[RCI_LATIN1_COUNT];
    stbtt_packedchar extraOut[RCI_LATIN1_COUNT];
    int              nExtra = 0;
    for (int i = 0; i < RCI_LATIN1_COUNT; i++) {
        int g = RCI_LATIN1_FIRST - RCI_FIRST_CHAR + i;
        if (rci_font_bit_get(slot->want, g) && !rci_font_bit_get(slot->blocked, g)) {
            extraG[nExtra]    = g;
            extraCp[nExtra++] = rci_font_pack_codepoint(slot->symbolShift,
                                                        RCI_LATIN1_FIRST + i);
        }
    }

    stbtt_pack_range ranges[2] = {
        { .font_size = bakeSize,
          .first_unicode_codepoint_in_range =
              rci_font_pack_codepoint(slot->symbolShift, RCI_FIRST_CHAR),
          .num_chars = RCI_ASCII_COUNT, .chardata_for_range = slot->chars },
        { .font_size = bakeSize, .array_of_unicode_codepoints = extraCp,
          .num_chars = nExtra, .chardata_for_range = extraOut },
    };

    if (filtering) {
        ranges[0].first_unicode_codepoint_in_range = 0;
        ranges[0].array_of_unicode_codepoints      = asciiCp;
        ranges[0].num_chars                        = nAscii;
        ranges[0].chardata_for_range               = asciiOut;
    }
    int nRanges = nExtra > 0 ? 2 : 1;

    stbrp_context *rp      = (stbrp_context *)rci_font_f.pc.pack_info;
    stbrp_node    *rpNodes = (stbrp_node *)rci_font_f.pc.nodes;
    static stbrp_node nodesSave[RCI_ATLAS_W];
    stbrp_context  ctxSave = *rp;

    if (ctxSave.num_nodes > RCI_ATLAS_W) {
        rci_core_log(RC_LOG_ERROR,
                "rc_font: rect-pack node count %d exceeds the %d-node snapshot "
                "pool (the vendored rasteriser changed its allocation); refusing "
                "the bake",
                ctxSave.num_nodes, RCI_ATLAS_W);
        return false;
    }
    memcpy(nodesSave, rpNodes, (size_t)ctxSave.num_nodes * sizeof(*rpNodes));

    bool packed;
    for (;;) {
        stbtt_PackSetOversampling(&rci_font_f.pc, h, v);
        packed = stbtt_PackFontRanges(&rci_font_f.pc, ttf, 0, ranges, nRanges) != 0;
        if (packed)
            break;
        *rp = ctxSave;
        memcpy(rpNodes, nodesSave, (size_t)ctxSave.num_nodes * sizeof(*rpNodes));
        for (const stbrp_node *n = rp->active_head; n && n->next; n = n->next) {
            int x0 = n->x, x1 = n->next->x;
            if (x1 > RCI_ATLAS_W) x1 = RCI_ATLAS_W;
            if (x0 >= x1) continue;
            for (int y = n->y; y < RCI_ATLAS_H; y++)
                memset(rci_font_f.bitmap + (size_t)y * RCI_ATLAS_W + (size_t)x0,
                       0, (size_t)(x1 - x0));
        }
        if (h <= 1u && v <= 1u)
            break;
        if (h > 1u) h >>= 1;
        if (v > 1u) v >>= 1;
        slot->osH = h;
        slot->osV = v;
    }

    if (packed && !speculative && (h != reqH || v != reqV) && !slot->osDowngradeLogged) {
        slot->osDowngradeLogged = true;
        rci_core_log(RC_LOG_WARNING,
                "rc_font: the %dx%d glyph atlas could not hold this face at %.0f px "
                "on screen with %ux%u oversampling; it is sharpened at %ux%u "
                "instead. Load "
                "fewer or smaller faces, lower RC_AppOptions.fontOversample, or "
                "build with a larger RC_FONT_ATLAS_W/H.",
                RCI_ATLAS_W, RCI_ATLAS_H, (double)bakeSize, reqH, reqV, h, v);
    }
    if (!packed) {

        if (!speculative)
            rci_core_log(RC_LOG_ERROR, "rc_font: atlas full packing @ %.0fpx; font dropped",
                    (double)bakeSize);
        return false;
    }

    memset(slot->baked, 0, sizeof(slot->baked));

    memset(slot->refused, 0, sizeof(slot->refused));
    if (filtering) {

        memset(slot->chars, 0, (size_t)RCI_ASCII_COUNT * sizeof(slot->chars[0]));
        for (int i = 0; i < nAscii; i++) {
            slot->chars[asciiG[i]] = asciiOut[i];
            rci_font_bit_set(slot->baked, asciiG[i]);
        }
    } else {
        for (int g = 0; g < RCI_ASCII_COUNT; g++)
            rci_font_bit_set(slot->baked, g);
    }
    for (int i = 0; i < nExtra; i++) {
        slot->chars[extraG[i]] = extraOut[i];
        rci_font_bit_set(slot->baked, extraG[i]);
    }

    int a = 0, d = 0, gap = 0;
    stbtt_GetFontVMetrics(&info, &a, &d, &gap);
    float scale    = stbtt_ScaleForPixelHeight(&info, bakeSize);

    if (filtering) {
        for (int g = 0; g < RCI_GLYPH_COUNT; g++) {
            if (!rci_font_bit_get(slot->blocked, g))
                continue;
            int adv = 0, lsb = 0;
            stbtt_GetCodepointHMetrics(
                &info, rci_font_pack_codepoint(slot->symbolShift, g + RCI_FIRST_CHAR),
                &adv, &lsb);
            memset(&slot->chars[g], 0, sizeof slot->chars[g]);
            slot->chars[g].xadvance = (float)adv * scale;
            rci_font_bit_set(slot->baked, g);
        }
    }
    slot->bakeSize = bakeSize;
    slot->ascent   = (float)a * scale;
    slot->descent  = (float)(-d) * scale;
    slot->lineGap  = (float)gap * scale;
    slot->loaded   = true;
    return true;
}

static bool rci_font_pack_one(RCI_FontSlot *slot, int g) {
    if (!slot->ttf || !rci_font_f.packing || slot->bakeSize <= 0.0f)
        return false;

    int cp = rci_font_pack_codepoint(slot->symbolShift, g + RCI_FIRST_CHAR);
    stbtt_pack_range r = {
        .font_size = slot->bakeSize,
        .first_unicode_codepoint_in_range = cp,
        .num_chars = 1,
        .chardata_for_range = &slot->chars[g],
    };
    stbtt_PackSetOversampling(&rci_font_f.pc, slot->osH, slot->osV);
    if (!stbtt_PackFontRanges(&rci_font_f.pc, slot->ttf, 0, &r, 1))
        return false;

    rci_font_bit_set(slot->baked, g);
    rci_font_atlas_touched();
    return true;
}

static bool rci_font_glyph_ensure(RCI_FontSlot *slot, int g) {
    if (rci_font_bit_get(slot->baked, g))
        return true;

    if (rci_font_bit_get(slot->blocked, g))
        return false;

    if (rci_font_bit_get(slot->refused, g))
        return false;
    rci_font_bit_set(slot->want, g);
    if (rci_font_f.frozen)
        return false;
    if (rci_font_pack_one(slot, g))
        return true;
    rci_font_bit_set(slot->refused, g);
    return false;
}

void rci_font_freeze(bool frozen) {
    rci_font_f.frozen = frozen;
}

static int rci_font_next_slot(void) {

    for (int i = 1; i < rci_font_f.count; i++) {
        if (!rci_font_f.slots[i].loaded && !rci_font_f.slots[i].ttf)
            return i;
    }
    if (rci_font_f.count < RC_MAX_FONTS)
        return rci_font_f.count;
    rci_core_log(RC_LOG_ERROR, "rc_font: table full (%d), ignoring font", RC_MAX_FONTS);
    return -1;
}

static uint16_t rci_font_bake(const unsigned char *ttf, long len, float authoredSize,
                              bool copy) {
    int next = rci_font_next_slot();
    if (next < 0)
        return 0;
    uint16_t      id   = (uint16_t)next;
    RCI_FontSlot *slot = &rci_font_f.slots[id];

    slot->facePropsLogged   = false;
    slot->osDowngradeLogged = false;

    unsigned char *keep = NULL;
    if (copy) {
        keep = (unsigned char *)malloc((size_t)len);
        if (!keep) {
            rci_core_log(RC_LOG_ERROR, "rc_font: TTF retain alloc failed; dropping font");
            return 0;
        }
        memcpy(keep, ttf, (size_t)len);
    }

    const bool canReclaim = rci_font_f.staleRects && !rci_font_f.frozen;
    if (!rci_font_pack_slot(slot, ttf, len, authoredSize * rci_font_eff_scale,
                             canReclaim)) {
        bool recovered = false;
        if (canReclaim && rci_font_rebake_all( false))
            recovered = rci_font_pack_slot(slot, ttf, len,
                                           authoredSize * rci_font_eff_scale,
                                            false);
        if (!recovered) {
            free(keep);
            return 0;
        }
    }

    slot->authoredSize = authoredSize;
    if (copy) {
        slot->ttf = keep; slot->ttfLen = len; slot->ttfOwned = true;
    } else {
        slot->ttf = ttf; slot->ttfLen = len; slot->ttfOwned = false;
    }

    if (id == (uint16_t)rci_font_f.count)
        rci_font_f.count++;
    rci_font_atlas_touched();
    return id;
}

bool rci_font_unload(uint16_t font) {

    if (font == 0 || (int)font >= rci_font_f.count)
        return false;

    if (rci_font_f.frozen)
        return false;
    RCI_FontSlot *slot = &rci_font_f.slots[font];
    if (!slot->loaded && !slot->ttf)
        return false;

    if (slot->ttfOwned)
        free((void *)slot->ttf);

    memset(slot, 0, sizeof *slot);

    rci_font_atlas_gen++;

    rci_font_f.staleRects = true;
    return true;
}

static bool rci_font_rebake_all(bool speculative) {
    if (!rci_font_f.bitmap) return true;
    if (rci_font_f.packing) { stbtt_PackEnd(&rci_font_f.pc); rci_font_f.packing = false; }

    if (!stbtt_PackBegin(&rci_font_f.pc, rci_font_f.bitmap, RCI_ATLAS_W, RCI_ATLAS_H, 0, 1, NULL)) {
        rci_core_log(RC_LOG_ERROR,
                "rc_font: could not rebuild the glyph atlas at the new display "
                "density; the previously baked glyphs are kept");
        return false;
    }
    rci_font_f.packing = true;

    rci_font_f.staleRects = false;
    bool all_fit = true;
    for (int i = 0; i < rci_font_f.count; i++) {
        RCI_FontSlot *s = &rci_font_f.slots[i];
        if (!s->ttf) { s->loaded = false; continue; }
        s->loaded = rci_font_pack_slot(s, s->ttf, s->ttfLen,
                                  s->authoredSize * rci_font_eff_scale, speculative);
        if (!s->loaded) {
            all_fit = false;

            if (speculative)
                break;

        }
    }
    rci_font_atlas_touched();
    return all_fit;
}

static void rci_font_report_kept_downgrades(void) {
    int i;

    for (i = 0; i < rci_font_f.count; i++) {
        RCI_FontSlot *s = &rci_font_f.slots[i];
        unsigned      reqH, reqV;

        if (!s->loaded || s->osDowngradeLogged)
            continue;
        rci_font_oversample_for(s->bakeSize, &reqH, &reqV);
        if (s->osH == reqH && s->osV == reqV)
            continue;

        s->osDowngradeLogged = true;
        rci_core_log(RC_LOG_WARNING,
                "rc_font: the %dx%d glyph atlas could not hold this face at %.0f px "
                "on screen with %ux%u oversampling; it is sharpened at %ux%u "
                "instead. Load fewer or smaller faces, lower "
                "RC_AppOptions.fontOversample, or build with a larger "
                "RC_FONT_ATLAS_W/H.",
                RCI_ATLAS_W, RCI_ATLAS_H, (double)s->bakeSize, reqH, reqV,
                s->osH, s->osV);
    }
}

void rci_font_set_effective_scale(float scale) {

    if (!(scale > 0.0f) || !isfinite(scale)) return;
    if (scale < 0.1f)  scale = 0.1f;
    if (scale > 16.0f) scale = 16.0f;

    if (fabsf(scale - rci_font_eff_scale) <= 0.01f * rci_font_eff_scale) return;

    float prev = rci_font_eff_scale;
    rci_font_eff_scale = scale;
    if (rci_font_rebake_all( true)) {
        rci_font_eff_held = false;
        rci_font_report_kept_downgrades();
        return;
    }

    float lo = prev, hi = scale;
    for (int i = 0; i < RCI_EFF_FIT_STEPS && hi - lo > 0.01f * lo; i++) {
        float mid = 0.5f * (lo + hi);
        rci_font_eff_scale = mid;
        if (rci_font_rebake_all( true)) lo = mid;
        else                                      hi = mid;
    }

    rci_font_eff_scale = lo;
    rci_font_rebake_all( false);

    if (!rci_font_eff_held) {
        rci_font_eff_held = true;
        rci_core_log(RC_LOG_WARNING,
                "rc_font: the %dx%d glyph atlas is full at effective scale %.2f; "
                "text holds near %.2f and can no longer follow the zoom. Load fewer "
                "or smaller faces, or build with a larger RC_FONT_ATLAS_W/H.",
                RCI_ATLAS_W, RCI_ATLAS_H, (double)scale, (double)lo);
    }
}

uint16_t rci_font_load(const char *path, float size) {
    if (!path) { rci_core_log(RC_LOG_ERROR, "rc_font_load: null path"); return 0; }
    if (!rci_font_f.packing) {

        rci_core_log(RC_LOG_ERROR,
                "rc_font_load: no glyph atlas yet; load fonts after rcInitWindow / "
                "rcAppCreate, or list them in RC_AppOptions.fontPath and .fontSizes");
        return 0;
    }

    if (!rci_font_size_in_band(size)) {

        rci_core_log(RC_LOG_ERROR,
                "rc_font_load: size %g for '%s' is outside the accepted %g to %g px range",
                (double)size, path, (double)RCI_FONT_SIZE_MIN, (double)RCI_FONT_SIZE_MAX);
        return 0;
    }

    if (rci_font_next_slot() < 0)
        return 0;

    long len = 0;
    unsigned char *ttf = rci_font_read_file(path, &len);
    if (!ttf) { rci_core_log(RC_LOG_ERROR, "rc_font_load: cannot read '%s'", path); return 0; }

    uint16_t id = rci_font_bake(ttf, len, size,  true);
    free(ttf);
    return id;
}

uint16_t rci_font_load_default(void) {
#ifndef RC_NO_BUNDLED_FONT

    if (rci_font_f.count == 0 && rci_font_f.packing)
        return rci_font_bake(rci_font_roboto_ttf, (long)rci_font_roboto_ttf_len,
                             RCI_DEFAULT_FONT_SIZE,  false);

    if (!rci_font_f.packing)
        rci_core_log(RC_LOG_ERROR,
                "rc_font_load_default: not initialised; no text will render");
#else
    if (rci_font_f.count == 0)
        rci_core_log(RC_LOG_WARNING,
                "rc_font: no font loaded; bundled font disabled (RC_NO_BUNDLED_FONT)");
#endif
    return 0;
}

uint16_t rci_font_load_default_size(float size) {
#ifndef RC_NO_BUNDLED_FONT
    if (!rci_font_f.packing) {
        rci_core_log(RC_LOG_ERROR,
                "rc_font_load_default_size: not initialised; no text will render");
        return 0;
    }

    if (!rci_font_size_in_band(size)) {
        rci_core_log(RC_LOG_ERROR,
                "rc_font_load_default_size: size %g is outside the accepted %g to %g px range",
                (double)size, (double)RCI_FONT_SIZE_MIN, (double)RCI_FONT_SIZE_MAX);
        return 0;
    }
    return rci_font_bake(rci_font_roboto_ttf, (long)rci_font_roboto_ttf_len, size,  false);
#else
    (void)size;

    RCI_LOG_WARN_ONCE("rc_font_load_default_size: bundled font disabled (RC_NO_BUNDLED_FONT)");
    return 0;
#endif
}

static RCI_FontSlot *rci_font_slot_or_default(uint16_t font) {
    if (font < rci_font_f.count && rci_font_f.slots[font].loaded) return &rci_font_f.slots[font];
    if (rci_font_f.count > 0 && rci_font_f.slots[0].loaded)       return &rci_font_f.slots[0];
    return NULL;
}

uint16_t rci_font_size(uint16_t font) {

    const RCI_FontSlot *s = rci_font_slot_or_default(font);
    return s ? (uint16_t)(s->authoredSize + 0.5f) : (uint16_t)RCI_DEFAULT_FONT_SIZE;
}

float rci_font_bake_size(uint16_t font) {
    if (font < rci_font_f.count && rci_font_f.slots[font].loaded)
        return rci_font_f.slots[font].bakeSize;
    return 0.0f;
}

float rci_font_effective_scale(void) {
    return rci_font_eff_scale;
}

static int rci_font_glyph_slot(unsigned int cp) {
    if (cp >= RCI_FIRST_CHAR   && cp <= RCI_ASCII_LAST) return (int)(cp - RCI_FIRST_CHAR);
    if (cp >= RCI_LATIN1_FIRST && cp <= RCI_LAST_CHAR)  return (int)(cp - RCI_FIRST_CHAR);
    return -1;
}

#define RCI_SUBST_REPORT_MAX 8

static int rci_font_glyph_slot_fallback(unsigned int cp) {
    static unsigned int seen[RCI_SUBST_REPORT_MAX];
    static int          seen_n;
    static int          seen_full_reported;

    int g = rci_font_glyph_slot(cp);
    if (g >= 0 || cp <= (unsigned int)RCI_LAST_CHAR) return g;

    for (int i = 0; i < seen_n; i++)
        if (seen[i] == cp) return rci_font_glyph_slot('?');

    if (seen_n < RCI_SUBST_REPORT_MAX) {
        seen[seen_n++] = cp;
        rci_core_log(RC_LOG_WARNING,
            "RayClay text: U+%04X is past the baked glyph cap U+%04X, so it draws "
            "as '?'. RayClay bakes ASCII plus Latin-1; raise RC_FONT_LAST_CODEPOINT "
            "to widen it, but the cost is linear in the cap, not in what you draw. "
            "Each distinct codepoint is reported once, up to %d of them.",
            cp, (unsigned int)RCI_LAST_CHAR, RCI_SUBST_REPORT_MAX);
    } else if (!seen_full_reported) {
        seen_full_reported = 1;
        rci_core_log(RC_LOG_WARNING,
            "RayClay text: more than %d distinct codepoints are past the baked "
            "glyph cap U+%04X. Further ones are substituted with '?' SILENTLY. "
            "This is a reporting limit, not a drawing one.",
            RCI_SUBST_REPORT_MAX, (unsigned int)RCI_LAST_CHAR);
    }
    return rci_font_glyph_slot('?');
}

int rci_font_utf8_decode(const char *s, const char *end, unsigned int *cp) {
    return rci_font_utf8_decode_one(s, end, cp);
}

float rci_font_measure(uint16_t font, float size, const char *begin, const char *end) {
    if (!begin || end <= begin) return 0.0f;
    RCI_FontSlot *s = rci_font_slot_or_default(font);
    if (!s || s->bakeSize <= 0.0f) return 0.0f;

    float scale = size / s->bakeSize;
    float width = 0.0f;
    for (const char *p = begin; p < end;) {
        unsigned int cp;
        p += rci_font_utf8_decode(p, end, &cp);
        int g = rci_font_glyph_slot_fallback(cp);
        if (g < 0)
            continue;
        if (!rci_font_glyph_ensure(s, g))
            g = rci_font_glyph_slot('?');
        width += s->chars[g].xadvance;
    }
    return width * scale;
}

void rci_font_v_metrics(uint16_t font, float size,
                       float *ascent, float *descent, float *line_gap) {
    const RCI_FontSlot *s = rci_font_slot_or_default(font);
    float scale = (s && s->bakeSize > 0.0f) ? size / s->bakeSize : 1.0f;
    if (ascent)   *ascent   = s ? s->ascent  * scale : size;
    if (descent)  *descent  = s ? s->descent * scale : 0.0f;
    if (line_gap) *line_gap = s ? s->lineGap * scale : 0.0f;
}

static inline bool rci_font_glyph_quad_at(RCI_FontSlot *s, float scale, unsigned int codepoint,
                                   float *xpos, float *ypos, RCI_GlyphQuad *out) {
    int g = rci_font_glyph_slot_fallback(codepoint);
    if (g < 0) return false;

    if (!rci_font_bit_get(s->baked, g)) {
        rci_font_bit_set(s->want, g);
        g = rci_font_glyph_slot('?');
    }

    float lx = 0.0f, ly = 0.0f;
    stbtt_aligned_quad q;
    stbtt_GetPackedQuad(s->chars, RCI_ATLAS_W, RCI_ATLAS_H, g, &lx, &ly, &q, 0);

    out->x0 = *xpos + q.x0 * scale;
    out->y0 = *ypos + q.y0 * scale;
    out->x1 = *xpos + q.x1 * scale;
    out->y1 = *ypos + q.y1 * scale;

    out->u0 = s->chars[g].x0; out->v0 = s->chars[g].y0;
    out->u1 = s->chars[g].x1; out->v1 = s->chars[g].y1;

    *xpos += lx * scale;
    return true;
}

bool rci_font_glyph_quad(uint16_t font, float size, unsigned int codepoint,
                        float *xpos, float *ypos, RCI_GlyphQuad *out) {
    if (!xpos || !ypos || !out) return false;
    RCI_FontSlot *s = rci_font_slot_or_default(font);
    if (!s || s->bakeSize <= 0.0f) return false;
    return rci_font_glyph_quad_at(s, size / s->bakeSize, codepoint, xpos, ypos, out);
}

int rci_font_run_quads(uint16_t font, float size,
                      const char *begin, const char *end, float letterSpacing,
                      float *xpos, float *ypos,
                      RCI_GlyphQuad *out, int max, const char **next) {
    const char *p = begin;
    int         written = 0, consumed = 0;

    if (next) *next = begin;
    if (!begin || !end || !xpos || !ypos || !out || max <= 0)
        return 0;

    RCI_FontSlot *s = rci_font_slot_or_default(font);
    if (!s || s->bakeSize <= 0.0f)
        return 0;
    float scale = size / s->bakeSize;

    while (p < end && consumed < max) {
        unsigned int  cp;
        RCI_GlyphQuad q;

        if (consumed > 0 && letterSpacing != 0.0f)
            *xpos += letterSpacing;

        p += rci_font_utf8_decode(p, end, &cp);
        consumed++;

        if (!rci_font_glyph_quad_at(s, scale, cp, xpos, ypos, &q))
            continue;

        if (q.x0 == q.x1 || q.y0 == q.y1)
            continue;
        out[written++] = q;
    }
    if (next) *next = p;
    return written;
}

const unsigned char *rci_font_atlas_pixels(int *w, int *h) {
    if (w) *w = RCI_ATLAS_W;
    if (h) *h = RCI_ATLAS_H;
    return rci_font_f.bitmap;
}

