#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>
#include <stdbool.h>
#include <stdint.h>

#ifndef M_PI
    #define M_PI 3.14159265358979323846
#endif

typedef enum { RCI_SVG_ROUND_LINE, RCI_SVG_POLYLINE, RCI_SVG_CIRCLE_STROKE,
               RCI_SVG_RRECT_STROKE, RCI_SVG_FILLED_POLY, RCI_SVG_FILLED_CIRCLE,
               RCI_SVG_FILLED_ELLIPSE } RCI_SvgOpKind;

typedef struct {
    RCI_SvgOpKind kind;
    float p[5];
    int   pointOff, pointCount;
    float stroke;
    bool  closed;
    bool  baked;
    RC_Color color;
} RCI_SvgOp;

#define RCI_SVG_MAX_OPS 512
#define RCI_SVG_MAX_POINTS 8192
#define RCI_SVG_MAX_WARN 16

#define RCI_SVG_RUNTIME_MAX_PTS RC_ICON_MAX_PTS

typedef struct {
    float viewW, viewH;
    RCI_SvgOp ops[RCI_SVG_MAX_OPS]; int opCount;
    RC_IconPoint points[RCI_SVG_MAX_POINTS]; int pointCount;
    bool colored;
    bool ok; char err[160];
    const char *warn[RCI_SVG_MAX_WARN]; int warnCount;
} RCI_SvgIcon;

#define RCI_SVG_MAX_SHAPES 512
#define RCI_SVG_MAX_SHAPE_POINTS 4096
#define RCI_SVG_MAX_ATTRS 32
#define RCI_SVG_MAX_DEPTH 64

typedef struct { float x, y; } RCI_SvgPoint;

typedef enum { RCI_SVG_PAINT_NONE, RCI_SVG_PAINT_CURRENT, RCI_SVG_PAINT_BAKED } RCI_SvgPaintKind;
typedef struct {
    RCI_SvgPaintKind kind;
    RC_Color color;
} RCI_SvgPaint;

typedef enum { RCI_SVG_SHAPE_PATH, RCI_SVG_SHAPE_RECT, RCI_SVG_SHAPE_CIRCLE, RCI_SVG_SHAPE_ELLIPSE } RCI_SvgShapeKind;

typedef struct {
    RCI_SvgShapeKind kind;

    int   ptOff, ptCount;
    bool  closed;

    float x, y, w, h, rx, ry;
    float cx, cy, r;
    float strokeWidth;
    RCI_SvgPaint fill, stroke;
} RCI_SvgShape;

typedef struct {
    RCI_SvgShape  shapes[RCI_SVG_MAX_SHAPES];  int shapeCount;
    RCI_SvgPoint  pts[RCI_SVG_MAX_SHAPE_POINTS]; int ptCount;
    int   curveSteps;
    float arcDeg;
    RCI_SvgIcon  *icon;
    bool  overflow;
} RCI_SvgParse;

static void rci_svg_str_copy(char *dst, const char *src, size_t cap) {
    size_t n;
    if (!dst || cap == 0) {
        return;
    }
    for (n = 0; n + 1 < cap && src && src[n] != '\0'; n++) {
        dst[n] = src[n];
    }
    dst[n] = '\0';
}

static const char *const rci_svg_warn_dropped_msg =
    "further diagnostics for this file were dropped; fix the ones above and reload";

static void rci_svg_warn(RCI_SvgIcon *icon, const char *msg) {
    if (!icon || icon->warnCount >= RCI_SVG_MAX_WARN) {
        return;
    }
    for (int i = 0; i < icon->warnCount; i++) {
        if (icon->warn[i] == msg) {
            return;
        }
    }

    if (icon->warnCount == RCI_SVG_MAX_WARN - 1) {
        icon->warn[icon->warnCount++] = rci_svg_warn_dropped_msg;
        return;
    }
    icon->warn[icon->warnCount++] = msg;
}

static bool rci_svg_is_cmd_char(char c) {
    switch (c) {
    case 'A': case 'a': case 'C': case 'c': case 'H': case 'h':
    case 'L': case 'l': case 'M': case 'm': case 'Q': case 'q':
    case 'S': case 's': case 'T': case 't': case 'V': case 'v':
    case 'Z': case 'z':
        return true;
    default:
        return false;
    }
}

static bool rci_svg_scan_float(const char *s, int len, int *i, float *out) {
    int j = *i;
    int start = j;
    if (j < len && (s[j] == '+' || s[j] == '-')) {
        j++;
    }
    int digitsBefore = 0;
    while (j < len && isdigit((unsigned char)s[j])) {
        j++; digitsBefore++;
    }
    int digitsAfter = 0;
    if (j < len && s[j] == '.') {
        j++;
        while (j < len && isdigit((unsigned char)s[j])) {
            j++; digitsAfter++;
        }
    }
    if (digitsBefore == 0 && digitsAfter == 0) {
        return false;
    }

    if (j < len && (s[j] == 'e' || s[j] == 'E')) {
        int k = j + 1;
        if (k < len && (s[k] == '+' || s[k] == '-')) {
            k++;
        }
        int expDigits = 0;
        while (k < len && isdigit((unsigned char)s[k])) {
            k++; expDigits++;
        }
        if (expDigits > 0) {
            j = k;
        }
    }

    char buf[64];
    int n = j - start;
    if (n <= 0 || n >= (int)sizeof(buf)) {
        return false;
    }
    memcpy(buf, s + start, (size_t)n);
    buf[n] = '\0';
    *out = (float)strtod(buf, NULL);
    *i = j;
    return true;
}

static bool rci_svg_scan_flag(const char *s, int len, int *i, bool *out) {
    if (*i >= len || (s[*i] != '0' && s[*i] != '1')) {
        return false;
    }
    *out = (s[*i] == '1');
    (*i)++;
    return true;
}

static void rci_svg_skip_sep(const char *s, int len, int *i) {
    while (*i < len && (isspace((unsigned char)s[*i]) || s[*i] == ',')) {
        (*i)++;
    }
}

static int rci_svg_comment_end(const char *s, int len, int from)
{
    for (int j = from; j + 2 < len; j++) {
        if (s[j] == '-' && s[j + 1] == '-' && s[j + 2] == '>') {
            return j + 3;
        }
    }
    return -1;
}

static bool rci_svg_nearly_same(RCI_SvgPoint a, RCI_SvgPoint b) {
    const float eps = 1e-6f;
    return fabsf(a.x - b.x) <= eps && fabsf(a.y - b.y) <= eps;
}

static RCI_SvgPoint rci_svg_cubic(RCI_SvgPoint p0, RCI_SvgPoint p1,
                                RCI_SvgPoint p2, RCI_SvgPoint p3, float t) {
    float mt = 1.0f - t;
    RCI_SvgPoint r;
    r.x = mt * mt * mt * p0.x + 3.0f * mt * mt * t * p1.x
        + 3.0f * mt * t * t * p2.x + t * t * t * p3.x;
    r.y = mt * mt * mt * p0.y + 3.0f * mt * mt * t * p1.y
        + 3.0f * mt * t * t * p2.y + t * t * t * p3.y;
    return r;
}

static RCI_SvgPoint rci_svg_quad(RCI_SvgPoint p0, RCI_SvgPoint p1, RCI_SvgPoint p2, float t) {
    float mt = 1.0f - t;
    RCI_SvgPoint r;
    r.x = mt * mt * p0.x + 2.0f * mt * t * p1.x + t * t * p2.x;
    r.y = mt * mt * p0.y + 2.0f * mt * t * p1.y + t * t * p2.y;
    return r;
}

static float rci_svg_angle_between(float ux, float uy, float vx, float vy) {
    float dot = ux * vx + uy * vy;
    float det = ux * vy - uy * vx;
    return atan2f(det, dot);
}

static bool rci_svg_push_pt(RCI_SvgParse *ps, RCI_SvgPoint p) {
    if (ps->ptCount >= RCI_SVG_MAX_SHAPE_POINTS) {
        if (!ps->overflow) {
            rci_svg_warn(ps->icon, "shape-point budget exhausted; geometry truncated");
        }
        ps->overflow = true;
        return false;
    }
    ps->pts[ps->ptCount].x = p.x;
    ps->pts[ps->ptCount].y = p.y;
    ps->ptCount++;
    return true;
}

static bool rci_svg_finite_pt(RCI_SvgPoint p) {
    return isfinite(p.x) && isfinite(p.y);
}

static void rci_svg_arc(RCI_SvgParse *ps, RCI_SvgPoint start, float rx, float ry,
                        float rotDeg, bool largeArc, bool sweep, RCI_SvgPoint end,
                        float maxSegDeg) {
    if (rci_svg_nearly_same(start, end)) {
        return;
    }

    if (!rci_svg_finite_pt(end)) {
        rci_svg_warn(ps->icon, "path arc has a non-finite endpoint - segment skipped");
        return;
    }
    if (!rci_svg_finite_pt(start) || !isfinite(rx) || !isfinite(ry) || !isfinite(rotDeg)) {

        rci_svg_warn(ps->icon, "path arc has a non-finite radius or start - drawn as a line");
        rci_svg_push_pt(ps, end);
        return;
    }
    rx = fabsf(rx);
    ry = fabsf(ry);
    if (rx == 0.0f || ry == 0.0f) {
        rci_svg_push_pt(ps, end);
        return;
    }

    float phi = (float)(fmod((double)rotDeg, 360.0) * M_PI / 180.0);
    float cosPhi = cosf(phi);
    float sinPhi = sinf(phi);

    float dx2 = (start.x - end.x) / 2.0f;
    float dy2 = (start.y - end.y) / 2.0f;

    float x1p = cosPhi * dx2 + sinPhi * dy2;
    float y1p = -sinPhi * dx2 + cosPhi * dy2;

    float lam = (x1p * x1p) / (rx * rx) + (y1p * y1p) / (ry * ry);
    if (lam > 1.0f) {
        float scale = sqrtf(lam);
        rx *= scale;
        ry *= scale;
    }

    float rx2 = rx * rx;
    float ry2 = ry * ry;
    float x1p2 = x1p * x1p;
    float y1p2 = y1p * y1p;

    float denom = rx2 * y1p2 + ry2 * x1p2;
    if (denom == 0.0f) {
        rci_svg_push_pt(ps, end);
        return;
    }

    float sign = (largeArc == sweep) ? -1.0f : 1.0f;
    float factorSq = (rx2 * ry2 - rx2 * y1p2 - ry2 * x1p2) / denom;
    if (factorSq < 0.0f) {
        factorSq = 0.0f;
    }
    float factor = sign * sqrtf(factorSq);

    float cxp = factor * (rx * y1p / ry);
    float cyp = factor * (-ry * x1p / rx);

    float cx = cosPhi * cxp - sinPhi * cyp + (start.x + end.x) / 2.0f;
    float cy = sinPhi * cxp + cosPhi * cyp + (start.y + end.y) / 2.0f;

    float v1x = (x1p - cxp) / rx, v1y = (y1p - cyp) / ry;
    float v2x = (-x1p - cxp) / rx, v2y = (-y1p - cyp) / ry;

    float theta1 = rci_svg_angle_between(1.0f, 0.0f, v1x, v1y);
    float delta = rci_svg_angle_between(v1x, v1y, v2x, v2y);

    if (!sweep && delta > 0.0f) {
        delta -= 2.0f * (float)M_PI;
    } else if (sweep && delta < 0.0f) {
        delta += 2.0f * (float)M_PI;
    }

    if (!isfinite(cx) || !isfinite(cy) || !isfinite(theta1) || !isfinite(delta)) {
        rci_svg_warn(ps->icon, "path arc geometry overflowed - drawn as a line to its endpoint");
        rci_svg_push_pt(ps, end);
        return;
    }

    float maxSeg = maxSegDeg > 1.0f ? maxSegDeg : 1.0f;
    float deltaDeg = fabsf(delta) * 180.0f / (float)M_PI;
    int steps = (int)ceilf(deltaDeg / maxSeg);
    if (steps < 4) {
        steps = 4;
    }

    for (int k = 1; k <= steps; k++) {
        float t = (float)k / (float)steps;
        float theta = theta1 + delta * t;
        RCI_SvgPoint p;
        if (k == steps) {

            p = end;
        } else {
            p.x = cx + cosPhi * rx * cosf(theta) - sinPhi * ry * sinf(theta);
            p.y = cy + sinPhi * rx * cosf(theta) + cosPhi * ry * sinf(theta);
        }
        rci_svg_push_pt(ps, p);
    }
}

static int rci_svg_hexval(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return 10 + c - 'a';
    if (c >= 'A' && c <= 'F') return 10 + c - 'A';
    return -1;
}

static bool rci_svg_hex2(const char *s, int *out) {
    int hi = rci_svg_hexval(s[0]);
    int lo = rci_svg_hexval(s[1]);
    if (hi < 0 || lo < 0) {
        return false;
    }
    *out = hi * 16 + lo;
    return true;
}

typedef struct { const char *name; unsigned char r, g, b, a; } RCI_SvgNamedColor;

static const RCI_SvgNamedColor rci_svg_named[] = {
    { "black", 0, 0, 0, 255 },       { "white", 255, 255, 255, 255 },
    { "red", 255, 0, 0, 255 },       { "green", 0, 128, 0, 255 },
    { "lime", 0, 255, 0, 255 },      { "blue", 0, 0, 255, 255 },
    { "navy", 0, 0, 128, 255 },      { "teal", 0, 128, 128, 255 },
    { "aqua", 0, 255, 255, 255 },    { "cyan", 0, 255, 255, 255 },
    { "yellow", 255, 255, 0, 255 },  { "gold", 255, 215, 0, 255 },
    { "orange", 255, 165, 0, 255 },  { "brown", 165, 42, 42, 255 },
    { "purple", 128, 0, 128, 255 },  { "magenta", 255, 0, 255, 255 },
    { "fuchsia", 255, 0, 255, 255 }, { "pink", 255, 192, 203, 255 },
    { "olive", 128, 128, 0, 255 },   { "maroon", 128, 0, 0, 255 },
    { "silver", 192, 192, 192, 255 },{ "gray", 128, 128, 128, 255 },
    { "grey", 128, 128, 128, 255 },  { "transparent", 0, 0, 0, 0 },
};

static int rci_svg_lower_trim(const char *v, int len, char *buf, int cap) {
    int a = 0, b = len;
    while (a < b && isspace((unsigned char)v[a])) a++;
    while (b > a && isspace((unsigned char)v[b - 1])) b--;
    int n = b - a;
    if (n >= cap) {
        n = cap - 1;
    }
    for (int i = 0; i < n; i++) {
        buf[i] = (char)tolower((unsigned char)v[a + i]);
    }
    buf[n] = '\0';
    return n;
}

static RCI_SvgPaint rci_svg_parse_color(const char *v, int len) {
    RCI_SvgPaint p;
    p.kind = RCI_SVG_PAINT_NONE;
    p.color = (RC_Color){ 0, 0, 0, 0 };
    if (!v) {
        return p;
    }

    int a = 0, b = len;
    while (a < b && isspace((unsigned char)v[a])) a++;
    while (b > a && isspace((unsigned char)v[b - 1])) b--;
    const char *t = v + a;
    int tn = b - a;
    if (tn <= 0) {
        return p;
    }

    char low[64];
    rci_svg_lower_trim(v, len, low, (int)sizeof(low));
    if (strcmp(low, "none") == 0) {
        return p;
    }
    if (strcmp(low, "currentcolor") == 0) {
        p.kind = RCI_SVG_PAINT_CURRENT;
        return p;
    }

    if (t[0] == '#') {
        const char *h = t + 1;
        int hn = tn - 1;
        int r, g, bl, al;
        if (hn == 3) {
            int r1 = rci_svg_hexval(h[0]), g1 = rci_svg_hexval(h[1]), b1 = rci_svg_hexval(h[2]);
            if (r1 < 0 || g1 < 0 || b1 < 0) return p;
            r = r1 * 16 + r1; g = g1 * 16 + g1; bl = b1 * 16 + b1; al = 255;
        } else if (hn == 4) {
            int r1 = rci_svg_hexval(h[0]), g1 = rci_svg_hexval(h[1]);
            int b1 = rci_svg_hexval(h[2]), a1 = rci_svg_hexval(h[3]);
            if (r1 < 0 || g1 < 0 || b1 < 0 || a1 < 0) return p;
            r = r1 * 16 + r1; g = g1 * 16 + g1; bl = b1 * 16 + b1; al = a1 * 16 + a1;
        } else if (hn == 6) {
            if (!rci_svg_hex2(h, &r) || !rci_svg_hex2(h + 2, &g) || !rci_svg_hex2(h + 4, &bl)) return p;
            al = 255;
        } else if (hn == 8) {
            if (!rci_svg_hex2(h, &r) || !rci_svg_hex2(h + 2, &g) ||
                !rci_svg_hex2(h + 4, &bl) || !rci_svg_hex2(h + 6, &al)) return p;
        } else {
            return p;
        }
        p.kind = RCI_SVG_PAINT_BAKED;
        p.color = (RC_Color){ (float)r, (float)g, (float)bl, (float)al };
        return p;
    }

    for (size_t i = 0; i < sizeof(rci_svg_named) / sizeof(rci_svg_named[0]); i++) {
        if (strcmp(low, rci_svg_named[i].name) == 0) {
            p.kind = RCI_SVG_PAINT_BAKED;
            p.color = (RC_Color){ (float)rci_svg_named[i].r, (float)rci_svg_named[i].g,
                                    (float)rci_svg_named[i].b, (float)rci_svg_named[i].a };
            return p;
        }
    }
    return p;
}

typedef struct {
    char  name[32];
    const char *val;
    int   valLen;
} RCI_SvgAttr;

typedef struct {
    char  tag[32];
    RCI_SvgAttr attrs[RCI_SVG_MAX_ATTRS];
    int   attrCount;
    bool  selfClose;
    bool  isClose;
} RCI_SvgElem;

static const char *rci_svg_attr(const RCI_SvgElem *e, const char *name, int *lenOut) {
    for (int i = 0; i < e->attrCount; i++) {
        if (strcmp(e->attrs[i].name, name) == 0) {
            if (lenOut) *lenOut = e->attrs[i].valLen;
            return e->attrs[i].val;
        }
    }
    return NULL;
}

typedef enum {
    RCI_SVG_REF_W,
    RCI_SVG_REF_H,
    RCI_SVG_REF_DIAG
} RCI_SvgRef;

static float rci_svg_ref_length(const RCI_SvgIcon *icon, RCI_SvgRef ref) {
    if (!icon) {
        return 0.0f;
    }
    if (ref == RCI_SVG_REF_W) {
        return icon->viewW;
    }
    if (ref == RCI_SVG_REF_H) {
        return icon->viewH;
    }

    return sqrtf((icon->viewW * icon->viewW + icon->viewH * icon->viewH) * 0.5f);
}

static const char *const rci_svg_unit_suffix_msg =
    "a length carries a unit suffix this parser does not convert (pt pc mm cm in em ex rem); "
    "the bare number was kept as user units - write the converted number instead";

static bool rci_svg_unit_suffix_unconverted(const char *v, int len, int i) {
    static const char *const units[] = { "pt", "pc", "mm", "cm", "in", "em", "ex", "rem" };
    char u[4];
    int n = 0;

    while (i + n < len && n < 4) {
        char c = v[i + n];
        if (c >= 'A' && c <= 'Z') {
            c = (char)(c + ('a' - 'A'));
        } else if (c < 'a' || c > 'z') {
            break;
        }
        u[n++] = c;
    }
    if (n < 2 || n > 3) {
        return false;
    }
    for (size_t k = 0; k < sizeof(units) / sizeof(units[0]); k++) {
        if ((int)strlen(units[k]) == n && memcmp(units[k], u, (size_t)n) == 0) {
            return true;
        }
    }
    return false;
}

static bool rci_svg_scan_length(const char *v, int len, RCI_SvgIcon *icon,
                                RCI_SvgRef ref, float *out) {
    int i = 0;

    while (i < len) {
        int save = i;
        if (rci_svg_scan_float(v, len, &i, out)) {
            if (i < len && v[i] == '%') {
                float refLen = rci_svg_ref_length(icon, ref);
                if (refLen > 0.0f) {
                    *out = *out * 0.01f * refLen;
                } else {
                    rci_svg_warn(icon, "a percentage length has no viewport to resolve against; "
                                       "give the root <svg> a viewBox - the bare number was kept");
                }
            } else if (rci_svg_unit_suffix_unconverted(v, len, i)) {
                rci_svg_warn(icon, rci_svg_unit_suffix_msg);
            }
            return true;
        }
        i = save + 1;
    }
    return false;
}

static float rci_svg_attr_number(RCI_SvgIcon *icon, const RCI_SvgElem *e,
                                 const char *name, float def, RCI_SvgRef ref) {
    int len = 0;
    const char *v = rci_svg_attr(e, name, &len);
    float out;

    if (v && rci_svg_scan_length(v, len, icon, ref, &out)) {
        return out;
    }
    return def;
}

static bool rci_svg_css_property(const RCI_SvgElem *e, const char *name,
                                 const char **valOut, int *lenOut) {
    int styleLen = 0;
    const char *style = rci_svg_attr(e, "style", &styleLen);
    if (style) {
        int i = 0;
        while (i < styleLen) {
            int declStart = i;
            while (i < styleLen && style[i] != ';') {
                i++;
            }
            int declEnd = i;
            if (i < styleLen) {
                i++;
            }

            int colon = -1;
            for (int j = declStart; j < declEnd; j++) {
                if (style[j] == ':') { colon = j; break; }
            }
            if (colon < 0) {
                continue;
            }

            int ka = declStart, kb = colon;
            while (ka < kb && isspace((unsigned char)style[ka])) ka++;
            while (kb > ka && isspace((unsigned char)style[kb - 1])) kb--;
            int klen = kb - ka;
            if (klen == (int)strlen(name) && strncmp(style + ka, name, (size_t)klen) == 0) {
                int va = colon + 1, vb = declEnd;
                while (va < vb && isspace((unsigned char)style[va])) va++;
                while (vb > va && isspace((unsigned char)style[vb - 1])) vb--;
                *valOut = style + va;
                *lenOut = vb - va;
                return true;
            }
        }
    }
    const char *pres = rci_svg_attr(e, name, lenOut);
    if (pres) {
        *valOut = pres;
        return true;
    }
    return false;
}

static float rci_svg_stroke_width(RCI_SvgIcon *icon, const RCI_SvgElem *e, float inherited) {
    const char *v; int len; float out;

    if (rci_svg_css_property(e, "stroke-width", &v, &len) &&
        rci_svg_scan_length(v, len, icon, RCI_SVG_REF_DIAG, &out)) {
        return out;
    }
    return inherited;
}

static RCI_SvgPaint rci_svg_read_paint(const RCI_SvgElem *e, const char *attr,
                                     RCI_SvgPaint inherited, RCI_SvgIcon *icon) {
    const char *v; int len;
    if (!rci_svg_css_property(e, attr, &v, &len)) {
        return inherited;
    }
    RCI_SvgPaint p = rci_svg_parse_color(v, len);
    if (p.kind == RCI_SVG_PAINT_NONE) {

        char low[16];
        rci_svg_lower_trim(v, len, low, (int)sizeof(low));
        if (low[0] != '\0' && strcmp(low, "none") != 0) {
            if (strcmp(attr, "fill") == 0) {
                rci_svg_warn(icon, "unrecognised fill colour; shape paint dropped (use hex #rrggbb or a named colour)");
            } else {
                rci_svg_warn(icon, "unrecognised stroke colour; shape paint dropped (use hex #rrggbb or a named colour)");
            }
        }
    }
    return p;
}

static void rci_svg_strip_ns(const char *raw, int len, char *out, int cap) {

    int start = 0;
    for (int i = 0; i < len; i++) {
        if (raw[i] == ':' || raw[i] == '}') {
            start = i + 1;
        }
    }
    int n = len - start;
    if (n >= cap) {
        n = cap - 1;
    }
    memcpy(out, raw + start, (size_t)n);
    out[n] = '\0';
}

static bool rci_svg_scan_element(const char *s, int len, int *i, RCI_SvgElem *e) {
    memset(e, 0, sizeof(*e));

    int p = *i;
    if (p < len && s[p] == '/') {
        e->isClose = true;
        p++;
    }

    int nameStart = p;
    while (p < len && !isspace((unsigned char)s[p]) && s[p] != '>' && s[p] != '/') {
        p++;
    }
    rci_svg_strip_ns(s + nameStart, p - nameStart, e->tag, (int)sizeof(e->tag));

    while (p < len) {
        while (p < len && isspace((unsigned char)s[p])) {
            p++;
        }
        if (p >= len) {
            return false;
        }
        if (s[p] == '>') {
            p++;
            *i = p;
            return true;
        }
        if (s[p] == '/') {
            e->selfClose = true;
            p++;

            while (p < len && isspace((unsigned char)s[p])) p++;
            if (p < len && s[p] == '>') {
                p++;
            }
            *i = p;
            return true;
        }

        int aStart = p;
        while (p < len && s[p] != '=' && !isspace((unsigned char)s[p]) && s[p] != '>' && s[p] != '/') {
            p++;
        }
        int aLen = p - aStart;
        char aname[32];
        rci_svg_strip_ns(s + aStart, aLen, aname, (int)sizeof(aname));

        while (p < len && isspace((unsigned char)s[p])) {
            p++;
        }
        const char *val = NULL;
        int vlen = 0;
        if (p < len && s[p] == '=') {
            p++;
            while (p < len && isspace((unsigned char)s[p])) {
                p++;
            }
            if (p < len && (s[p] == '"' || s[p] == '\'')) {
                char q = s[p];
                p++;
                int vStart = p;
                while (p < len && s[p] != q) {
                    p++;
                }
                val = s + vStart;
                vlen = p - vStart;
                if (p < len) {
                    p++;
                }
            } else {

                int vStart = p;
                while (p < len && !isspace((unsigned char)s[p]) && s[p] != '>' && s[p] != '/') {
                    p++;
                }
                val = s + vStart;
                vlen = p - vStart;
            }
        }
        if (aname[0] != '\0' && e->attrCount < RCI_SVG_MAX_ATTRS) {
            RCI_SvgAttr *at = &e->attrs[e->attrCount++];
            rci_svg_str_copy(at->name, aname, sizeof(at->name));
            at->val = val;
            at->valLen = vlen;
        }
    }
    return false;
}

static void rci_svg_parse_viewbox(RCI_SvgIcon *icon, const RCI_SvgElem *root,
                                  float *vx, float *vy, float *vw, float *vh) {
    int len = 0;
    const char *raw = rci_svg_attr(root, "viewBox", &len);
    if (!raw) {
        raw = rci_svg_attr(root, "viewbox", &len);
    }
    if (raw) {
        float vals[4];
        int n = 0, i = 0;
        while (i < len && n < 4) {
            rci_svg_skip_sep(raw, len, &i);
            if (i >= len) {
                break;
            }
            float out;
            int save = i;
            if (rci_svg_scan_float(raw, len, &i, &out)) {
                vals[n++] = out;
            } else {
                i = save + 1;
            }
        }
        if (n == 4) {
            *vx = vals[0]; *vy = vals[1]; *vw = vals[2]; *vh = vals[3];
            return;
        }
    }
    float width = rci_svg_attr_number(icon, root, "width", 24.0f, RCI_SVG_REF_W);
    float height = rci_svg_attr_number(icon, root, "height", width, RCI_SVG_REF_H);
    *vx = 0.0f; *vy = 0.0f; *vw = width; *vh = height;
}

static bool rci_svg_push_xy(RCI_SvgParse *ps, float x, float y) {
    RCI_SvgPoint p = { x, y };
    return rci_svg_push_pt(ps, p);
}

static int rci_svg_parse_points_attr(RCI_SvgParse *ps, const char *v, int len, int *offOut) {
    float nums[2];
    int have = 0;
    int start = ps->ptCount;
    *offOut = start;
    int i = 0;
    int pushed = 0;
    while (i < len) {
        rci_svg_skip_sep(v, len, &i);
        if (i >= len) {
            break;
        }
        float out;
        int save = i;
        if (!rci_svg_scan_float(v, len, &i, &out)) {
            i = save + 1;
            continue;
        }
        nums[have++] = out;
        if (have == 2) {
            if (!rci_svg_push_xy(ps, nums[0], nums[1])) {
                break;
            }
            pushed++;
            have = 0;
        }
    }
    return pushed;
}

static void rci_svg_parse_path_data(RCI_SvgParse *ps, const char *d, int len,
                                    float strokeWidth, RCI_SvgPaint fill, RCI_SvgPaint stroke);

static void rci_svg_flush_subpath(RCI_SvgParse *ps, int start, bool closed,
                                  float strokeWidth, RCI_SvgPaint fill, RCI_SvgPaint stroke) {
    int count = ps->ptCount - start;
    if (count < 2) {
        ps->ptCount = start;
        return;
    }
    if (closed && count >= 2 &&
        rci_svg_nearly_same(ps->pts[start], ps->pts[start + count - 1])) {
        ps->ptCount--;
        count--;
    }
    if (ps->shapeCount >= RCI_SVG_MAX_SHAPES) {
        if (!ps->overflow) {
            rci_svg_warn(ps->icon, "shape budget exhausted; remaining shapes skipped");
        }
        ps->overflow = true;
        return;
    }
    RCI_SvgShape *sh = &ps->shapes[ps->shapeCount++];
    memset(sh, 0, sizeof(*sh));
    sh->kind = RCI_SVG_SHAPE_PATH;
    sh->ptOff = start;
    sh->ptCount = count;
    sh->closed = closed;
    sh->strokeWidth = strokeWidth;
    sh->fill = fill;
    sh->stroke = stroke;
}

static void rci_svg_parse_path_data(RCI_SvgParse *ps, const char *d, int len,
                                    float strokeWidth, RCI_SvgPaint fill, RCI_SvgPaint stroke) {
    int i = 0;
    char command = 0;
    char prevCommand = 0;
    RCI_SvgPoint current = { 0.0f, 0.0f };
    RCI_SvgPoint startPt = { 0.0f, 0.0f };
    int subStart = ps->ptCount;
    bool haveSub = false;
    RCI_SvgPoint lastCubic = { 0.0f, 0.0f }; bool haveCubic = false;
    RCI_SvgPoint lastQuad = { 0.0f, 0.0f };  bool haveQuad = false;

    #define RCI_SVG_READ_FLOAT(dst) \
        do { \
            rci_svg_skip_sep(d, len, &i); \
            if (i >= len || rci_svg_is_cmd_char(d[i])) { goto malformed; } \
            int _save = i; \
            if (!rci_svg_scan_float(d, len, &i, &(dst))) { i = _save; goto malformed; } \
        } while (0)

    #define RCI_SVG_READ_FLAG(dst) \
        do { \
            rci_svg_skip_sep(d, len, &i); \
            if (!rci_svg_scan_flag(d, len, &i, &(dst))) { goto malformed; } \
        } while (0)

    for (;;) {
        rci_svg_skip_sep(d, len, &i);
        if (i >= len) {
            break;
        }
        if (rci_svg_is_cmd_char(d[i])) {
            command = d[i];
            i++;
        } else if (command == 0) {
            rci_svg_warn(ps->icon, "path data starts with numbers before a command; skipped remainder");
            break;
        }

        char upper = (char)toupper((unsigned char)command);
        bool relative = islower((unsigned char)command) != 0;

        if (upper == 'Z') {
            if (haveSub) {
                rci_svg_flush_subpath(ps, subStart, true, strokeWidth, fill, stroke);
            }
            subStart = ps->ptCount;
            haveSub = false;
            current = startPt;
            haveCubic = false;
            haveQuad = false;
            prevCommand = command;
            command = 0;
            continue;
        }

        if (upper != 'M' && upper != 'L' && upper != 'H' && upper != 'V' &&
            upper != 'C' && upper != 'S' && upper != 'Q' && upper != 'T' && upper != 'A') {
            rci_svg_warn(ps->icon, "unsupported path command; skipped");
            break;
        }

        bool firstMoveto = (upper == 'M');
        char curUpper = upper;

        while (i < len) {
            rci_svg_skip_sep(d, len, &i);
            if (i >= len || rci_svg_is_cmd_char(d[i])) {
                break;
            }
            if (curUpper == 'M') {
                float x, y;
                RCI_SVG_READ_FLOAT(x);
                RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint pt = relative ? (RCI_SvgPoint){ current.x + x, current.y + y }
                                         : (RCI_SvgPoint){ x, y };
                if (firstMoveto) {
                    if (haveSub) {
                        rci_svg_flush_subpath(ps, subStart, false, strokeWidth, fill, stroke);
                    }
                    subStart = ps->ptCount;
                    if (!rci_svg_push_pt(ps, pt)) { goto done; }
                    haveSub = true;
                    current = pt;
                    startPt = pt;
                    firstMoveto = false;
                    curUpper = 'L';
                } else {
                    if (!rci_svg_push_pt(ps, pt)) { goto done; }
                    current = pt;
                }
                haveCubic = false;
                haveQuad = false;
            } else if (curUpper == 'L') {
                float x, y;
                RCI_SVG_READ_FLOAT(x);
                RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x + x, current.y + y }
                                          : (RCI_SvgPoint){ x, y };
                if (!rci_svg_push_pt(ps, end)) { goto done; }
                current = end;
                haveCubic = false; haveQuad = false;
            } else if (curUpper == 'H') {
                float x;
                RCI_SVG_READ_FLOAT(x);
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x + x, current.y }
                                          : (RCI_SvgPoint){ x, current.y };
                if (!rci_svg_push_pt(ps, end)) { goto done; }
                current = end;
                haveCubic = false; haveQuad = false;
            } else if (curUpper == 'V') {
                float y;
                RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x, current.y + y }
                                          : (RCI_SvgPoint){ current.x, y };
                if (!rci_svg_push_pt(ps, end)) { goto done; }
                current = end;
                haveCubic = false; haveQuad = false;
            } else if (curUpper == 'C') {
                float x1, y1, x2, y2, x, y;
                RCI_SVG_READ_FLOAT(x1); RCI_SVG_READ_FLOAT(y1);
                RCI_SVG_READ_FLOAT(x2); RCI_SVG_READ_FLOAT(y2);
                RCI_SVG_READ_FLOAT(x);  RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint c1 = relative ? (RCI_SvgPoint){ current.x + x1, current.y + y1 } : (RCI_SvgPoint){ x1, y1 };
                RCI_SvgPoint c2 = relative ? (RCI_SvgPoint){ current.x + x2, current.y + y2 } : (RCI_SvgPoint){ x2, y2 };
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x + x, current.y + y } : (RCI_SvgPoint){ x, y };
                for (int step = 1; step <= ps->curveSteps; step++) {
                    RCI_SvgPoint pp = rci_svg_cubic(current, c1, c2, end, (float)step / (float)ps->curveSteps);
                    if (!rci_svg_push_pt(ps, pp)) { goto done; }
                }
                current = end;
                lastCubic = c2; haveCubic = true; haveQuad = false;
            } else if (curUpper == 'S') {
                float x2, y2, x, y;
                RCI_SVG_READ_FLOAT(x2); RCI_SVG_READ_FLOAT(y2);
                RCI_SVG_READ_FLOAT(x);  RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint c1;
                char pu = prevCommand ? (char)toupper((unsigned char)prevCommand) : 0;
                if ((pu == 'C' || pu == 'S') && haveCubic) {
                    c1 = (RCI_SvgPoint){ 2.0f * current.x - lastCubic.x, 2.0f * current.y - lastCubic.y };
                } else {
                    c1 = current;
                }
                RCI_SvgPoint c2 = relative ? (RCI_SvgPoint){ current.x + x2, current.y + y2 } : (RCI_SvgPoint){ x2, y2 };
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x + x, current.y + y } : (RCI_SvgPoint){ x, y };
                for (int step = 1; step <= ps->curveSteps; step++) {
                    RCI_SvgPoint pp = rci_svg_cubic(current, c1, c2, end, (float)step / (float)ps->curveSteps);
                    if (!rci_svg_push_pt(ps, pp)) { goto done; }
                }
                current = end;
                lastCubic = c2; haveCubic = true; haveQuad = false;
            } else if (curUpper == 'Q') {
                float x1, y1, x, y;
                RCI_SVG_READ_FLOAT(x1); RCI_SVG_READ_FLOAT(y1);
                RCI_SVG_READ_FLOAT(x);  RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint c = relative ? (RCI_SvgPoint){ current.x + x1, current.y + y1 } : (RCI_SvgPoint){ x1, y1 };
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x + x, current.y + y } : (RCI_SvgPoint){ x, y };
                for (int step = 1; step <= ps->curveSteps; step++) {
                    RCI_SvgPoint pp = rci_svg_quad(current, c, end, (float)step / (float)ps->curveSteps);
                    if (!rci_svg_push_pt(ps, pp)) { goto done; }
                }
                current = end;
                lastQuad = c; haveQuad = true; haveCubic = false;
            } else if (curUpper == 'T') {
                float x, y;
                RCI_SVG_READ_FLOAT(x); RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint c;
                char pu = prevCommand ? (char)toupper((unsigned char)prevCommand) : 0;
                if ((pu == 'Q' || pu == 'T') && haveQuad) {
                    c = (RCI_SvgPoint){ 2.0f * current.x - lastQuad.x, 2.0f * current.y - lastQuad.y };
                } else {
                    c = current;
                }
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x + x, current.y + y } : (RCI_SvgPoint){ x, y };
                for (int step = 1; step <= ps->curveSteps; step++) {
                    RCI_SvgPoint pp = rci_svg_quad(current, c, end, (float)step / (float)ps->curveSteps);
                    if (!rci_svg_push_pt(ps, pp)) { goto done; }
                }
                current = end;
                lastQuad = c; haveQuad = true; haveCubic = false;
            } else if (curUpper == 'A') {
                float rx, ry, rot, x, y;
                bool la, sw;
                RCI_SVG_READ_FLOAT(rx); RCI_SVG_READ_FLOAT(ry); RCI_SVG_READ_FLOAT(rot);
                RCI_SVG_READ_FLAG(la);  RCI_SVG_READ_FLAG(sw);
                RCI_SVG_READ_FLOAT(x);  RCI_SVG_READ_FLOAT(y);
                RCI_SvgPoint end = relative ? (RCI_SvgPoint){ current.x + x, current.y + y } : (RCI_SvgPoint){ x, y };
                rci_svg_arc(ps, current, rx, ry, rot, la, sw, end, ps->arcDeg);
                current = end;
                haveCubic = false; haveQuad = false;
            }
            prevCommand = command;
            continue;

        malformed:
            rci_svg_warn(ps->icon, "malformed path; skipped incomplete tail");

            while (i < len && !rci_svg_is_cmd_char(d[i])) {
                i++;
            }
            goto after_params;
        }

    after_params:

        if (command != 0 && (command == 'M' || command == 'm')) {
            command = islower((unsigned char)command) ? 'l' : 'L';
        }

        continue;
    }

done:
    if (haveSub) {
        rci_svg_flush_subpath(ps, subStart, false, strokeWidth, fill, stroke);
    }

    #undef RCI_SVG_READ_FLOAT
    #undef RCI_SVG_READ_FLAG
}

static const char *rci_svg_unsupported_hint(const char *tag) {
    static const char *const gradient =
        "gradients are not supported (SVG becomes icon ops); use a solid fill, or rcLoadImage + PNG";
    static const char *const filter =
        "SVG filters are not supported; bake the effect into the artwork, or use rcLoadImage + PNG";
    static const struct { const char *tag; const char *const *msg; } families[] = {
        { "linearGradient", &gradient }, { "radialGradient", &gradient }, { "stop", &gradient },
        { "filter", &filter },
    };
    static const char *const text_msg =
        "<text> is not supported; convert text to paths in your editor, or draw it with rcText";
    static const char *const image_msg =
        "<image> is not supported; load the raster directly with rcLoadImage";
    static const char *const ref_msg =
        "<use>/<symbol> references are not resolved; inline the shapes in your editor";
    static const char *const mask_msg =
        "<mask>/<clipPath> are not supported; flatten the artwork in your editor";
    static const char *const pattern_msg =
        "<pattern> fills are not supported; use a solid fill, or rcLoadImage + PNG";

    for (size_t i = 0; i < sizeof families / sizeof families[0]; i++) {
        if (strcmp(tag, families[i].tag) == 0) {
            return *families[i].msg;
        }
    }

    if (tag[0] == 'f' && tag[1] == 'e' && tag[2] != '\0') {
        return filter;
    }
    if (strcmp(tag, "text") == 0 || strcmp(tag, "tspan") == 0) {
        return text_msg;
    }
    if (strcmp(tag, "image") == 0) {
        return image_msg;
    }
    if (strcmp(tag, "use") == 0 || strcmp(tag, "symbol") == 0) {
        return ref_msg;
    }
    if (strcmp(tag, "mask") == 0 || strcmp(tag, "clipPath") == 0) {
        return mask_msg;
    }
    if (strcmp(tag, "pattern") == 0) {
        return pattern_msg;
    }
    return "unsupported SVG element skipped";
}

static const char *rci_svg_ignored_attr_hint(const char *name) {
    static const char *const transform_msg =
        "transform is ignored - shapes draw at their raw coordinates; "
        "flatten it in your editor, then reframe the viewBox around the art";
    static const char *const hidden_msg =
        "display/visibility are ignored, so a hidden element still DRAWS; "
        "delete the hidden layer in your editor";

    static const char *const opacity_msg =
        "opacity is ignored - shapes draw fully opaque; bake the blend into the "
        "fill colour in your editor";
    static const char *const fillrule_msg =
        "fill-rule is ignored, so an evenodd hole fills SOLID; flatten the path "
        "in your editor";
    static const char *const dash_msg =
        "stroke-dasharray is ignored - dashed strokes draw solid; convert the "
        "dashes to separate paths";

    static const struct { const char *name; const char *const *msg; } ignored[] = {
        { "transform",      &transform_msg },
        { "display",        &hidden_msg    },
        { "visibility",     &hidden_msg    },
        { "opacity",        &opacity_msg   },
        { "fill-opacity",   &opacity_msg   },
        { "stroke-opacity", &opacity_msg   },
        { "fill-rule",      &fillrule_msg  },
        { "clip-rule",      &fillrule_msg  },
        { "stroke-dasharray", &dash_msg    },
    };

    for (size_t i = 0; i < sizeof ignored / sizeof ignored[0]; i++) {
        if (strcmp(name, ignored[i].name) == 0) {
            return *ignored[i].msg;
        }
    }
    return NULL;
}

static void rci_svg_add_shape(RCI_SvgParse *ps, RCI_SvgShape sh) {
    if (ps->shapeCount >= RCI_SVG_MAX_SHAPES) {
        if (!ps->overflow) {
            rci_svg_warn(ps->icon, "shape budget exhausted; remaining shapes skipped");
        }
        ps->overflow = true;
        return;
    }
    ps->shapes[ps->shapeCount++] = sh;
}

static void rci_svg_collect(RCI_SvgParse *ps, const char *s, int len, int *i,
                            float inhStrokeW, RCI_SvgPaint inhFill,
                            RCI_SvgPaint inhStroke, int depth);

static void rci_svg_report_ignored_attrs(RCI_SvgParse *ps, const RCI_SvgElem *e) {
    for (int a = 0; a < e->attrCount; a++) {
        const char *hint = rci_svg_ignored_attr_hint(e->attrs[a].name);
        if (hint) {
            rci_svg_warn(ps->icon, hint);
        }
    }
}

static bool rci_svg_tag_is_definition(const char *tag) {
    static const char *const defn[] = {
        "defs", "clipPath", "mask", "pattern", "marker",
        "symbol", "linearGradient", "radialGradient", "filter"
    };
    size_t k;
    for (k = 0; k < sizeof defn / sizeof defn[0]; k++)
        if (strcmp(tag, defn[k]) == 0)
            return true;
    return false;
}

static void rci_svg_handle_element(RCI_SvgParse *ps, const char *s, int len, int *i,
                                   const RCI_SvgElem *e, float inhStrokeW,
                                   RCI_SvgPaint inhFill, RCI_SvgPaint inhStroke, int depth) {
    float strokeWidth = rci_svg_stroke_width(ps->icon, e, inhStrokeW);
    RCI_SvgPaint fill = rci_svg_read_paint(e, "fill", inhFill, ps->icon);
    RCI_SvgPaint stroke = rci_svg_read_paint(e, "stroke", inhStroke, ps->icon);

    rci_svg_report_ignored_attrs(ps, e);

    const char *tag = e->tag;

    if (strcmp(tag, "path") == 0) {
        int dLen = 0;
        const char *d = rci_svg_attr(e, "d", &dLen);
        if (d && dLen > 0) {
            rci_svg_parse_path_data(ps, d, dLen, strokeWidth, fill, stroke);
        }
    } else if (strcmp(tag, "line") == 0) {
        RCI_SvgShape sh; memset(&sh, 0, sizeof(sh));
        sh.kind = RCI_SVG_SHAPE_PATH;
        int off = ps->ptCount;
        bool ok1 = rci_svg_push_xy(ps, rci_svg_attr_number(ps->icon, e, "x1", 0.0f, RCI_SVG_REF_W),
                               rci_svg_attr_number(ps->icon, e, "y1", 0.0f, RCI_SVG_REF_H));
        bool ok2 = rci_svg_push_xy(ps, rci_svg_attr_number(ps->icon, e, "x2", 0.0f, RCI_SVG_REF_W),
                               rci_svg_attr_number(ps->icon, e, "y2", 0.0f, RCI_SVG_REF_H));
        if (ok1 && ok2) {
            sh.ptOff = off; sh.ptCount = 2; sh.closed = false;
            sh.strokeWidth = strokeWidth; sh.fill = fill; sh.stroke = stroke;
            rci_svg_add_shape(ps, sh);
        }
    } else if (strcmp(tag, "polyline") == 0 || strcmp(tag, "polygon") == 0) {
        int pLen = 0;
        const char *pts = rci_svg_attr(e, "points", &pLen);
        if (pts && pLen > 0) {
            int off = 0;
            int n = rci_svg_parse_points_attr(ps, pts, pLen, &off);
            if (n >= 2) {
                RCI_SvgShape sh; memset(&sh, 0, sizeof(sh));
                sh.kind = RCI_SVG_SHAPE_PATH;
                sh.ptOff = off; sh.ptCount = n;
                sh.closed = (strcmp(tag, "polygon") == 0);
                sh.strokeWidth = strokeWidth; sh.fill = fill; sh.stroke = stroke;
                rci_svg_add_shape(ps, sh);
            } else {
                ps->ptCount = off;
            }
        }
    } else if (strcmp(tag, "rect") == 0) {
        float x = rci_svg_attr_number(ps->icon, e, "x", 0.0f, RCI_SVG_REF_W);
        float y = rci_svg_attr_number(ps->icon, e, "y", 0.0f, RCI_SVG_REF_H);
        float w = rci_svg_attr_number(ps->icon, e, "width", 0.0f, RCI_SVG_REF_W);
        float h = rci_svg_attr_number(ps->icon, e, "height", 0.0f, RCI_SVG_REF_H);
        float rx = rci_svg_attr_number(ps->icon, e, "rx", 0.0f, RCI_SVG_REF_W);

        float ry = rci_svg_attr_number(ps->icon, e, "ry", rx, RCI_SVG_REF_H);
        if (w > 0.0f && h > 0.0f) {
            RCI_SvgShape sh; memset(&sh, 0, sizeof(sh));
            sh.kind = RCI_SVG_SHAPE_RECT;
            sh.x = x; sh.y = y; sh.w = w; sh.h = h; sh.rx = rx; sh.ry = ry;
            sh.strokeWidth = strokeWidth; sh.fill = fill; sh.stroke = stroke;
            rci_svg_add_shape(ps, sh);
        }
    } else if (strcmp(tag, "circle") == 0) {
        float cx = rci_svg_attr_number(ps->icon, e, "cx", 0.0f, RCI_SVG_REF_W);
        float cy = rci_svg_attr_number(ps->icon, e, "cy", 0.0f, RCI_SVG_REF_H);
        float r = rci_svg_attr_number(ps->icon, e, "r", 0.0f, RCI_SVG_REF_DIAG);
        if (r > 0.0f) {
            RCI_SvgShape sh; memset(&sh, 0, sizeof(sh));
            sh.kind = RCI_SVG_SHAPE_CIRCLE;
            sh.cx = cx; sh.cy = cy; sh.r = r;
            sh.strokeWidth = strokeWidth; sh.fill = fill; sh.stroke = stroke;
            rci_svg_add_shape(ps, sh);
        }
    } else if (strcmp(tag, "ellipse") == 0) {
        float cx = rci_svg_attr_number(ps->icon, e, "cx", 0.0f, RCI_SVG_REF_W);
        float cy = rci_svg_attr_number(ps->icon, e, "cy", 0.0f, RCI_SVG_REF_H);
        float rx = rci_svg_attr_number(ps->icon, e, "rx", 0.0f, RCI_SVG_REF_W);
        float ry = rci_svg_attr_number(ps->icon, e, "ry", 0.0f, RCI_SVG_REF_H);
        if (rx > 0.0f && ry > 0.0f) {
            RCI_SvgShape sh; memset(&sh, 0, sizeof(sh));
            sh.kind = RCI_SVG_SHAPE_ELLIPSE;
            sh.cx = cx; sh.cy = cy; sh.rx = rx; sh.ry = ry;
            sh.strokeWidth = strokeWidth; sh.fill = fill; sh.stroke = stroke;
            rci_svg_add_shape(ps, sh);
        }
    } else if (strcmp(tag, "svg") == 0 || strcmp(tag, "g") == 0 ||
               strcmp(tag, "defs") == 0 || strcmp(tag, "title") == 0 ||
               strcmp(tag, "desc") == 0 || strcmp(tag, "style") == 0) {

    } else {
        rci_svg_warn(ps->icon, rci_svg_unsupported_hint(tag));
    }

    if (!e->selfClose) {
        const bool isDefinition  = rci_svg_tag_is_definition(tag);
        const int  savedShapes   = ps->shapeCount;
        const int  savedPts      = ps->ptCount;
        const bool savedOverflow = ps->overflow;

        rci_svg_collect(ps, s, len, i, strokeWidth, fill, stroke, depth + 1);

        if (isDefinition) {
            ps->shapeCount = savedShapes;
            ps->ptCount    = savedPts;
            ps->overflow   = savedOverflow;
        }
    }
}

static void rci_svg_collect(RCI_SvgParse *ps, const char *s, int len, int *i,
                            float inhStrokeW, RCI_SvgPaint inhFill,
                            RCI_SvgPaint inhStroke, int depth) {
    if (depth > RCI_SVG_MAX_DEPTH) {
        rci_svg_warn(ps->icon, "element nesting too deep; subtree skipped");
        return;
    }
    while (*i < len) {

        while (*i < len && s[*i] != '<') {
            (*i)++;
        }
        if (*i >= len) {
            return;
        }

        if (*i + 1 < len && (s[*i + 1] == '!' || s[*i + 1] == '?')) {
            if (*i + 3 < len && strncmp(s + *i, "<!--", 4) == 0) {
                int end = rci_svg_comment_end(s, len, *i);
                if (end < 0) {
                    *i = len;
                    return;
                }
                *i = end;
            } else {
                while (*i < len && s[*i] != '>') {
                    (*i)++;
                }
                if (*i < len) {
                    (*i)++;
                }
            }
            continue;
        }
        (*i)++;
        RCI_SvgElem e;
        if (!rci_svg_scan_element(s, len, i, &e)) {

            *i = len;
            return;
        }
        if (e.isClose) {
            return;
        }
        rci_svg_handle_element(ps, s, len, i, &e, inhStrokeW, inhFill, inhStroke, depth);
    }
}

static const char *const rci_svg_pointbudget_msg =
    "icon point budget exhausted; geometry truncated";

static int rci_svg_emit_circle_ring(RCI_SvgIcon *out, float cx, float cy,
                                    float rx, float ry, int count) {
    int off = out->pointCount;
    for (int k = 0; k < count; k++) {
        if (out->pointCount >= RCI_SVG_MAX_POINTS) {
            rci_svg_warn(out, rci_svg_pointbudget_msg);
            break;
        }
        float ang = 2.0f * (float)M_PI * (float)k / (float)count;
        out->points[out->pointCount].x = cx + cosf(ang) * rx;
        out->points[out->pointCount].y = cy + sinf(ang) * ry;
        out->pointCount++;
    }
    return off;
}

static int rci_svg_copy_points(RCI_SvgIcon *out, const RCI_SvgParse *ps,
                               int srcOff, int srcCount, int *countOut) {
    int off = out->pointCount;
    int n = 0;
    for (int k = 0; k < srcCount; k++) {
        if (out->pointCount >= RCI_SVG_MAX_POINTS) {
            rci_svg_warn(out, rci_svg_pointbudget_msg);
            break;
        }
        out->points[out->pointCount].x = ps->pts[srcOff + k].x;
        out->points[out->pointCount].y = ps->pts[srcOff + k].y;
        out->pointCount++;
        n++;
    }
    *countOut = n;
    return off;
}

static bool rci_svg_push_op(RCI_SvgIcon *out, RCI_SvgOp op) {
    if (out->opCount >= RCI_SVG_MAX_OPS) {
        rci_svg_warn(out, "op budget exhausted; remaining ops skipped");
        return false;
    }

    if (op.pointCount > RCI_SVG_RUNTIME_MAX_PTS) {
        rci_svg_warn(out, "a path exceeds the runtime point cap; its tail "
                          "vertices will be dropped when drawn - simplify the SVG");
    }
    out->ops[out->opCount++] = op;
    return true;
}

static void rci_svg_rect_corners(RCI_SvgIcon *out, const RCI_SvgShape *sh, int *offOut, int *countOut) {
    int off = out->pointCount;
    struct { float x, y; } corners[4] = {
        { sh->x, sh->y },
        { sh->x + sh->w, sh->y },
        { sh->x + sh->w, sh->y + sh->h },
        { sh->x, sh->y + sh->h },
    };
    int n = 0;
    for (int k = 0; k < 4; k++) {
        if (out->pointCount >= RCI_SVG_MAX_POINTS) {
            rci_svg_warn(out, rci_svg_pointbudget_msg);
            break;
        }
        out->points[out->pointCount].x = corners[k].x;
        out->points[out->pointCount].y = corners[k].y;
        out->pointCount++;
        n++;
    }
    *offOut = off;
    *countOut = n;
}

static bool rci_svg_paint_is_baked(RCI_SvgPaint p) {
    return p.kind == RCI_SVG_PAINT_BAKED;
}

static bool rci_svg_paint_is_paint(RCI_SvgPaint p) {
    return p.kind == RCI_SVG_PAINT_BAKED || p.kind == RCI_SVG_PAINT_CURRENT;
}

static RC_Color rci_svg_baked_color(RCI_SvgPaint p) {
    if (p.kind == RCI_SVG_PAINT_BAKED) {
        return p.color;
    }
    return (RC_Color){ 0, 0, 0, 255 };
}

static void rci_svg_build_mono(RCI_SvgIcon *out, const RCI_SvgParse *ps) {
    for (int si = 0; si < ps->shapeCount; si++) {
        const RCI_SvgShape *sh = &ps->shapes[si];
        RCI_SvgOp op; memset(&op, 0, sizeof(op));
        op.baked = false;

        if (sh->kind == RCI_SVG_SHAPE_RECT) {
            if (sh->rx > 0.0f) {
                if (sh->ry > 0.0f && fabsf(sh->rx - sh->ry) > 1e-6f) {
                    rci_svg_warn(out, "rect rx != ry; using rx for the rounded stroke");
                }
                op.kind = RCI_SVG_RRECT_STROKE;
                op.p[0] = sh->x; op.p[1] = sh->y; op.p[2] = sh->w; op.p[3] = sh->h; op.p[4] = sh->rx;
                op.stroke = sh->strokeWidth;
                rci_svg_push_op(out, op);
            } else {
                int off, count;
                rci_svg_rect_corners(out, sh, &off, &count);
                op.kind = RCI_SVG_POLYLINE;
                op.pointOff = off; op.pointCount = count;
                op.closed = true; op.stroke = sh->strokeWidth;
                rci_svg_push_op(out, op);
            }
        } else if (sh->kind == RCI_SVG_SHAPE_CIRCLE) {
            op.kind = RCI_SVG_CIRCLE_STROKE;
            op.p[0] = sh->cx; op.p[1] = sh->cy; op.p[2] = sh->r;
            op.stroke = sh->strokeWidth;
            rci_svg_push_op(out, op);
        } else if (sh->kind == RCI_SVG_SHAPE_ELLIPSE) {
            if (fabsf(sh->rx - sh->ry) <= 1e-6f) {
                op.kind = RCI_SVG_CIRCLE_STROKE;
                op.p[0] = sh->cx; op.p[1] = sh->cy; op.p[2] = sh->rx;
                op.stroke = sh->strokeWidth;
                rci_svg_push_op(out, op);
            } else {

                int off = rci_svg_emit_circle_ring(out, sh->cx, sh->cy, sh->rx, sh->ry, 64);
                op.kind = RCI_SVG_POLYLINE;
                op.pointOff = off; op.pointCount = out->pointCount - off;
                op.closed = true; op.stroke = sh->strokeWidth;
                rci_svg_push_op(out, op);
            }
        } else {
            if (sh->ptCount == 2 && !sh->closed) {
                op.kind = RCI_SVG_ROUND_LINE;
                op.p[0] = ps->pts[sh->ptOff].x; op.p[1] = ps->pts[sh->ptOff].y;
                op.p[2] = ps->pts[sh->ptOff + 1].x; op.p[3] = ps->pts[sh->ptOff + 1].y;
                op.stroke = sh->strokeWidth;
                rci_svg_push_op(out, op);
            } else {
                int count;
                int off = rci_svg_copy_points(out, ps, sh->ptOff, sh->ptCount, &count);
                op.kind = RCI_SVG_POLYLINE;
                op.pointOff = off; op.pointCount = count;
                op.closed = sh->closed; op.stroke = sh->strokeWidth;
                rci_svg_push_op(out, op);
            }
        }
    }
}

static void rci_svg_build_colored(RCI_SvgIcon *out, RCI_SvgParse *ps) {

    bool usesColor = false, usesBaked = false;

    for (int si = 0; si < ps->shapeCount; si++) {
        const RCI_SvgShape *sh = &ps->shapes[si];
        bool hasFill = rci_svg_paint_is_paint(sh->fill);
        bool hasStroke = rci_svg_paint_is_paint(sh->stroke);
        if (!hasFill && !hasStroke) {
            continue;
        }

        if (hasFill) {
            RCI_SvgPaint fp = sh->fill;

            bool fbaked = (fp.kind == RCI_SVG_PAINT_BAKED);
            if (fbaked) usesBaked = true;
            if (fp.kind == RCI_SVG_PAINT_CURRENT) usesColor = true;
            RC_Color fc = rci_svg_baked_color(fp);
            if (sh->kind == RCI_SVG_SHAPE_CIRCLE) {
                RCI_SvgOp op; memset(&op, 0, sizeof(op));
                op.kind = RCI_SVG_FILLED_CIRCLE; op.baked = fbaked; op.color = fc;
                op.p[0] = sh->cx; op.p[1] = sh->cy; op.p[2] = sh->r;
                rci_svg_push_op(out, op);
            } else if (sh->kind == RCI_SVG_SHAPE_ELLIPSE) {
                RCI_SvgOp op; memset(&op, 0, sizeof(op));
                op.baked = fbaked; op.color = fc;
                if (fabsf(sh->rx - sh->ry) <= 1e-6f) {
                    op.kind = RCI_SVG_FILLED_CIRCLE;
                    op.p[0] = sh->cx; op.p[1] = sh->cy; op.p[2] = sh->rx;
                } else {
                    op.kind = RCI_SVG_FILLED_ELLIPSE;
                    op.p[0] = sh->cx; op.p[1] = sh->cy; op.p[2] = sh->rx; op.p[3] = sh->ry;
                }
                rci_svg_push_op(out, op);
            } else if (sh->kind == RCI_SVG_SHAPE_RECT) {
                if (sh->rx > 0.0f) {
                    rci_svg_warn(out, "a filled rounded rect draws with SQUARE corners; convert it to a path in your editor if the rounding matters");
                }
                int off, count;
                rci_svg_rect_corners(out, sh, &off, &count);
                RCI_SvgOp op; memset(&op, 0, sizeof(op));
                op.kind = RCI_SVG_FILLED_POLY; op.baked = fbaked; op.color = fc;
                op.pointOff = off; op.pointCount = count;
                rci_svg_push_op(out, op);
            } else {
                if (sh->ptCount >= 3) {
                    int count;
                    int off = rci_svg_copy_points(out, ps, sh->ptOff, sh->ptCount, &count);
                    RCI_SvgOp op; memset(&op, 0, sizeof(op));
                    op.kind = RCI_SVG_FILLED_POLY; op.baked = fbaked; op.color = fc;
                    op.pointOff = off; op.pointCount = count;
                    rci_svg_push_op(out, op);
                } else if (!hasStroke) {
                    rci_svg_warn(out, "degenerate filled path (<3 points) skipped");
                }
            }
        }

        if (hasStroke && sh->strokeWidth > 0.0f) {
            RCI_SvgPaint spnt = sh->stroke;
            bool sbaked = (spnt.kind == RCI_SVG_PAINT_BAKED);
            if (sbaked) usesBaked = true;
            if (spnt.kind == RCI_SVG_PAINT_CURRENT) usesColor = true;
            RC_Color sc = rci_svg_baked_color(spnt);
            if (sh->kind == RCI_SVG_SHAPE_CIRCLE) {
                RCI_SvgOp op; memset(&op, 0, sizeof(op));
                op.kind = RCI_SVG_CIRCLE_STROKE; op.baked = sbaked; op.color = sc;
                op.p[0] = sh->cx; op.p[1] = sh->cy; op.p[2] = sh->r;
                op.stroke = sh->strokeWidth;
                rci_svg_push_op(out, op);
            } else if (sh->kind == RCI_SVG_SHAPE_ELLIPSE) {
                if (fabsf(sh->rx - sh->ry) <= 1e-6f) {
                    RCI_SvgOp op; memset(&op, 0, sizeof(op));
                    op.kind = RCI_SVG_CIRCLE_STROKE; op.baked = sbaked; op.color = sc;
                    op.p[0] = sh->cx; op.p[1] = sh->cy; op.p[2] = sh->rx;
                    op.stroke = sh->strokeWidth;
                    rci_svg_push_op(out, op);
                } else {
                    int off = rci_svg_emit_circle_ring(out, sh->cx, sh->cy, sh->rx, sh->ry, 64);
                    RCI_SvgOp op; memset(&op, 0, sizeof(op));
                    op.kind = RCI_SVG_POLYLINE; op.baked = sbaked; op.color = sc;
                    op.pointOff = off; op.pointCount = out->pointCount - off;
                    op.closed = true; op.stroke = sh->strokeWidth;
                    rci_svg_push_op(out, op);
                }
            } else if (sh->kind == RCI_SVG_SHAPE_RECT) {
                if (sh->rx > 0.0f) {
                    RCI_SvgOp op; memset(&op, 0, sizeof(op));
                    op.kind = RCI_SVG_RRECT_STROKE; op.baked = sbaked; op.color = sc;
                    op.p[0] = sh->x; op.p[1] = sh->y; op.p[2] = sh->w; op.p[3] = sh->h; op.p[4] = sh->rx;
                    op.stroke = sh->strokeWidth;
                    rci_svg_push_op(out, op);
                } else {
                    int off, count;
                    rci_svg_rect_corners(out, sh, &off, &count);
                    RCI_SvgOp op; memset(&op, 0, sizeof(op));
                    op.kind = RCI_SVG_POLYLINE; op.baked = sbaked; op.color = sc;
                    op.pointOff = off; op.pointCount = count;
                    op.closed = true; op.stroke = sh->strokeWidth;
                    rci_svg_push_op(out, op);
                }
            } else {
                if (sh->ptCount == 2 && !sh->closed) {
                    RCI_SvgOp op; memset(&op, 0, sizeof(op));
                    op.kind = RCI_SVG_ROUND_LINE; op.baked = sbaked; op.color = sc;
                    op.p[0] = ps->pts[sh->ptOff].x; op.p[1] = ps->pts[sh->ptOff].y;
                    op.p[2] = ps->pts[sh->ptOff + 1].x; op.p[3] = ps->pts[sh->ptOff + 1].y;
                    op.stroke = sh->strokeWidth;
                    rci_svg_push_op(out, op);
                } else {
                    int count;
                    int off = rci_svg_copy_points(out, ps, sh->ptOff, sh->ptCount, &count);
                    RCI_SvgOp op; memset(&op, 0, sizeof(op));
                    op.kind = RCI_SVG_POLYLINE; op.baked = sbaked; op.color = sc;
                    op.pointOff = off; op.pointCount = count;
                    op.closed = sh->closed; op.stroke = sh->strokeWidth;
                    rci_svg_push_op(out, op);
                }
            }
        }

    }

    if (usesColor && usesBaked) {

        rci_svg_warn(out, "this icon mixes currentColor with explicit colours: the "
                          "colour you pass to rcSvg tints only the currentColor "
                          "shapes, and the explicit ones keep their own");
    }
}

static bool rci_svg_parse_doc(const char *svg, int len, int curveSteps, float arcDeg, RCI_SvgIcon *out) {
    if (!out) {
        return false;
    }
    memset(out, 0, sizeof(*out));
    out->ok = false;

    if (!svg || len <= 0) {
        snprintf(out->err, sizeof(out->err), "empty SVG input");
        return false;
    }
    if (curveSteps < 2) {
        curveSteps = 2;
    }
    if (arcDeg <= 0.0f) {
        arcDeg = 7.5f;
    }

    RCI_SvgParse *ps = (RCI_SvgParse *)calloc(1, sizeof *ps);
    if (!ps) {
        rci_svg_str_copy(out->err, "out of memory allocating the SVG parse scratch",
                         sizeof(out->err));
        return false;
    }
    ps->curveSteps = curveSteps;
    ps->arcDeg = arcDeg;
    ps->icon = out;

    int i = 0;
    RCI_SvgElem root;
    bool haveRoot = false;
    while (i < len) {
        while (i < len && svg[i] != '<') {
            i++;
        }
        if (i >= len) {
            break;
        }
        if (i + 1 < len && (svg[i + 1] == '!' || svg[i + 1] == '?')) {
            if (i + 3 < len && strncmp(svg + i, "<!--", 4) == 0) {
                int end = rci_svg_comment_end(svg, len, i);
                if (end < 0) { i = len; break; }
                i = end;
            } else {
                while (i < len && svg[i] != '>') i++;
                if (i < len) i++;
            }
            continue;
        }
        i++;
        if (!rci_svg_scan_element(svg, len, &i, &root)) {
            snprintf(out->err, sizeof(out->err), "malformed root element");
            free(ps);
        return false;
        }
        if (!root.isClose) {
            haveRoot = true;
            break;
        }
    }
    if (!haveRoot) {

        snprintf(out->err, sizeof(out->err),
                 "no XML element found - is this file really an SVG?");
        free(ps);
        return false;
    }

    float vx, vy, vw, vh;
    rci_svg_parse_viewbox(out, &root, &vx, &vy, &vw, &vh);
    out->viewW = vw;
    out->viewH = vh;

    float rootStrokeW = rci_svg_stroke_width(out, &root, 2.0f);
    RCI_SvgPaint none = { RCI_SVG_PAINT_NONE, { 0, 0, 0, 0 } };
    RCI_SvgPaint rootFill = rci_svg_read_paint(&root, "fill", none, out);
    RCI_SvgPaint rootStroke = rci_svg_read_paint(&root, "stroke", none, out);

    const char *tag = root.tag;
    bool rootIsContainer = (strcmp(tag, "svg") == 0 || strcmp(tag, "g") == 0 ||
                            strcmp(tag, "defs") == 0 || strcmp(tag, "title") == 0 ||
                            strcmp(tag, "desc") == 0 || strcmp(tag, "style") == 0);
    if (!rootIsContainer) {

        rci_svg_handle_element(ps, svg, len, &i, &root, rootStrokeW, rootFill, rootStroke, 0);
    } else {

        rci_svg_report_ignored_attrs(ps, &root);
    }
    if (rootIsContainer && !root.selfClose) {
        rci_svg_collect(ps, svg, len, &i, rootStrokeW, rootFill, rootStroke, 1);
    }

    if (vx != 0.0f || vy != 0.0f) {
        for (int k = 0; k < ps->ptCount; k++) {
            ps->pts[k].x -= vx;
            ps->pts[k].y -= vy;
        }
        for (int s = 0; s < ps->shapeCount; s++) {
            RCI_SvgShape *sh = &ps->shapes[s];
            if (sh->kind == RCI_SVG_SHAPE_RECT) {
                sh->x -= vx; sh->y -= vy;
            } else if (sh->kind == RCI_SVG_SHAPE_CIRCLE || sh->kind == RCI_SVG_SHAPE_ELLIPSE) {
                sh->cx -= vx; sh->cy -= vy;
            }

        }
    }

    if (fabsf(vw - vh) > 1e-6f) {
        rci_svg_warn(out, "non-square viewBox; the art is scaled by its LARGER dimension, so it will not fill the box - square the viewBox in your editor");
    }

    bool colored = false, painted = false, paintless = false;
    for (int s = 0; s < ps->shapeCount; s++) {
        const RCI_SvgShape *sh = &ps->shapes[s];
        if (rci_svg_paint_is_baked(sh->fill) || rci_svg_paint_is_baked(sh->stroke)) {
            colored = true;
        }
        if (rci_svg_paint_is_paint(sh->fill) || rci_svg_paint_is_paint(sh->stroke)) {
            painted = true;
        } else {
            paintless = true;
        }
    }
    out->colored = colored;

    if (colored || (painted && !paintless)) {
        rci_svg_build_colored(out, ps);
    } else {
        rci_svg_build_mono(out, ps);
    }

    out->ok = true;
    free(ps);
    return true;
}

static void rci_svg_draw_ops(const RCI_SvgOp *ops, int opCount,
                             const RC_IconPoint *allPoints, float viewW, float viewH,
                             RC_BoundingBox bounds, RC_Color monoColor) {
    float viewBox = viewW > viewH ? viewW : viewH;

    if (!(viewBox > 0.0f) || !isfinite(bounds.width / viewBox)) {
        viewBox = 24.0f;
    }

    for (int oi = 0; oi < opCount; oi++) {
        const RCI_SvgOp *op = &ops[oi];
        RC_Color color = op->baked ? op->color : monoColor;
        const RC_IconPoint *pts = allPoints + op->pointOff;

        switch (op->kind) {
        case RCI_SVG_ROUND_LINE:
            rcIconDrawRoundLine(bounds, op->p[0], op->p[1], op->p[2], op->p[3],
                                  viewBox, op->stroke, color);
            break;
        case RCI_SVG_POLYLINE:
            rcIconDrawPolyline(bounds, pts, op->pointCount, viewBox,
                                 op->stroke, op->closed, color);
            break;
        case RCI_SVG_CIRCLE_STROKE:
            rcIconDrawCircleStroke(bounds, op->p[0], op->p[1], op->p[2],
                                     viewBox, op->stroke, color);
            break;
        case RCI_SVG_RRECT_STROKE:
            rcIconDrawRoundedRectStroke(bounds, op->p[0], op->p[1], op->p[2], op->p[3],
                                          op->p[4], viewBox, op->stroke, color);
            break;
        case RCI_SVG_FILLED_POLY:
            rcIconDrawFilledPolygon(bounds, pts, op->pointCount, viewBox, color);
            break;
        case RCI_SVG_FILLED_CIRCLE:
            rcIconDrawFilledCircle(bounds, op->p[0], op->p[1], op->p[2], viewBox, color);
            break;
        case RCI_SVG_FILLED_ELLIPSE:
            rcIconDrawFilledEllipse(bounds, op->p[0], op->p[1], op->p[2], op->p[3],
                                      viewBox, color);
            break;
        }
    }
}

struct RC_Svg {
    float         viewW, viewH;
    int           opCount, pointCount;
    RCI_SvgOp    *ops;
    RC_IconPoint *points;
};

static bool rci_svg_geometry_is_finite(const RCI_SvgIcon *icon, const char *whence,
                                       const char *entry) {
    for (int i = 0; i < icon->pointCount; i++) {
        if (!isfinite(icon->points[i].x) || !isfinite(icon->points[i].y)) {
            rci_core_log(RC_LOG_ERROR,
                         "%s: %s: point %d of %d is not finite - refusing to return a "
                         "handle holding undrawable geometry", entry, whence, i, icon->pointCount);
            return false;
        }
    }
    for (int i = 0; i < icon->opCount; i++) {
        const RCI_SvgOp *op = &icon->ops[i];
        if (!isfinite(op->stroke)) {
            rci_core_log(RC_LOG_ERROR, "%s: %s: op %d has a non-finite stroke width",
                         entry, whence, i);
            return false;
        }
        for (int k = 0; k < 5; k++) {
            if (!isfinite(op->p[k])) {
                rci_core_log(RC_LOG_ERROR,
                             "%s: %s: op %d parameter %d is not finite", entry, whence, i, k);
                return false;
            }
        }
    }
    if (!isfinite(icon->viewW) || !isfinite(icon->viewH)) {
        rci_core_log(RC_LOG_ERROR, "%s: %s: the viewBox is not finite", entry, whence);
        return false;
    }
    return true;
}

static RC_Svg *rci_svg_pack(const RCI_SvgIcon *icon, const char *whence,
                            const char *entry) {
    size_t opBytes  = (size_t)icon->opCount    * sizeof(RCI_SvgOp);
    size_t ptBytes  = (size_t)icon->pointCount * sizeof(RC_IconPoint);
    unsigned char *block = (unsigned char *)malloc(sizeof(RC_Svg) + opBytes + ptBytes);
    if (!block) {
        rci_core_log(RC_LOG_ERROR, "%s: %s: out of memory packing the parsed icon",
                     entry, whence);
        return NULL;
    }
    RC_Svg *svg = (RC_Svg *)block;
    svg->viewW      = icon->viewW;
    svg->viewH      = icon->viewH;
    svg->opCount    = icon->opCount;
    svg->pointCount = icon->pointCount;
    svg->ops    = (RCI_SvgOp *)(block + sizeof(RC_Svg));
    svg->points = (RC_IconPoint *)(block + sizeof(RC_Svg) + opBytes);
    if (opBytes) {
        memcpy(svg->ops, icon->ops, opBytes);
    }
    if (ptBytes) {
        memcpy(svg->points, icon->points, ptBytes);
    }
    return svg;
}

static RC_Svg *rci_svg_load_text(const char *bytes, int len, const char *whence,
                                 const char *entry) {
    if (!bytes || len <= 0) {

        if (!bytes) {
            rci_core_log(RC_LOG_ERROR, "%s: NULL SVG buffer", entry);
        } else {
            rci_core_log(RC_LOG_ERROR,
                         "%s: SVG buffer length is %d - expected the byte count",
                         entry, len);
        }
        return NULL;
    }
    RCI_SvgIcon *icon = (RCI_SvgIcon *)calloc(1, sizeof *icon);
    if (!icon) {
        rci_core_log(RC_LOG_ERROR, "%s: %s: out of memory allocating the parse scratch",
                     entry, whence);
        return NULL;
    }
    RC_Svg *out = NULL;
    if (!rci_svg_parse_doc(bytes, len, 16, 7.5f, icon) || !icon->ok) {
        rci_core_log(RC_LOG_ERROR, "%s: %s: %s", entry, whence,
                     icon->err[0] ? icon->err : "the SVG could not be parsed");
    } else {

        for (int w = 0; w < icon->warnCount; w++) {
            rci_core_log(RC_LOG_WARNING, "%s: %s: %s", entry, whence, icon->warn[w]);
        }
        if (icon->opCount == 0) {
            rci_core_log(RC_LOG_WARNING,
                         "%s: %s: parsed cleanly but produced nothing to draw - "
                         "it renders as empty. Any elements this parser does not "
                         "support are named in the warnings above.", entry, whence);
        }

        if (rci_svg_geometry_is_finite(icon, whence, entry)) {
            out = rci_svg_pack(icon, whence, entry);
        }
    }
    free(icon);
    return out;
}

RC_Svg *rcLoadSvgFromMemory(const char *bytes, int len) {
    return rci_svg_load_text(bytes, len, "<memory>", "rcLoadSvgFromMemory");
}

static RC_Svg *rci_svg_load_path(const char *path, const char *entry) {
    if (!path) {
        rci_core_log(RC_LOG_ERROR, "%s: NULL path", entry);
        return NULL;
    }

    long size = 0;
    RCI_FileStatus st = RCI_FILE_OK;
    char *text = (char *)rci_file_read(path, 8L << 20, &size, &st);
    if (!text) {
        switch (st) {
        case RCI_FILE_OPEN_FAILED:

            rci_core_log(RC_LOG_ERROR,
                         "%s: %s: cannot open the file - check the path and the file "
                         "permissions", entry, path);
            break;
        case RCI_FILE_NOT_REGULAR:

            rci_core_log(RC_LOG_ERROR,
                         "%s: %s: not a regular file - a directory, pipe or device "
                         "cannot be loaded as an SVG", entry, path);
            break;
        case RCI_FILE_TOO_BIG:

            rci_core_log(RC_LOG_ERROR, "%s: %s: %ld-byte file exceeds the 8 MiB SVG cap",
                         entry, path, size);
            break;
        case RCI_FILE_OOM:
            rci_core_log(RC_LOG_ERROR, "%s: %s: out of memory reading the file", entry, path);
            break;
        case RCI_FILE_SHORT_READ:
            rci_core_log(RC_LOG_ERROR, "%s: %s: short read", entry, path);
            break;
        case RCI_FILE_OK:
            break;
        }
        return NULL;
    }
    if (size == 0) {
        free(text);
        rci_core_log(RC_LOG_ERROR, "%s: %s: the file is empty", entry, path);
        return NULL;
    }
    RC_Svg *svg = rci_svg_load_text(text, (int)size, path, entry);
    free(text);
    return svg;
}

RC_Svg *rcLoadSvg(const char *path) {
    return rci_svg_load_path(path, "rcLoadSvg");
}

void rcUnloadSvg(RC_Svg **svg) {
    if (!svg || !*svg) {
        return;
    }

    rci_defer_free(*svg, free);
    *svg = NULL;
}

static void rci_svg_custom_draw(RC_BoundingBox bounds, RC_Color color, const void *userData) {
    const RC_Svg *svg = (const RC_Svg *)userData;
    if (!svg) {
        return;
    }
    rci_svg_draw_ops(svg->ops, svg->opCount, svg->points, svg->viewW, svg->viewH, bounds, color);
}

void rcSvgHandle(const RC_Svg *svg, float size, RC_Color color) {
    if (!svg) {
        return;
    }
    rcIconEmit(size, color, rci_svg_custom_draw, svg);
}

typedef struct {
    char     *path;
    uint64_t  hash;
    RC_Svg   *svg;
} RCI_SvgCacheEntry;

static RCI_SvgCacheEntry rci_svg_cache[RC_SVG_CACHE_MAX];
static int               rci_svg_cacheCount;

static void rci_svg_cache_shutdown(void);

static uint64_t rci_svg_path_hash(const char *p) {
    uint64_t h = 1469598103934665603ULL;
    for (; *p; p++) {
        h ^= (unsigned char)*p;
        h *= 1099511628211ULL;
    }
    return h;
}

static const RC_Svg *rci_svg_cache_get(const char *path) {
    uint64_t h = rci_svg_path_hash(path);
    for (int i = 0; i < rci_svg_cacheCount; i++) {
        if (rci_svg_cache[i].hash == h && strcmp(rci_svg_cache[i].path, path) == 0) {
            return rci_svg_cache[i].svg;
        }
    }
    if (rci_svg_cacheCount >= RC_SVG_CACHE_MAX) {
        static bool warned = false;
        if (!warned) {
            warned = true;
            rci_core_log(RC_LOG_WARNING,
                         "rcSvg: more than %d distinct paths; '%s' and any further ones draw "
                         "nothing. Raise RC_SVG_CACHE_MAX, or use rcLoadSvg/rcUnloadSvg and "
                         "manage the lifetime yourself.", RC_SVG_CACHE_MAX, path);
        }
        return NULL;
    }

    size_t len  = strlen(path) + 1;
    char  *copy = (char *)malloc(len);
    if (!copy) {
        return NULL;
    }
    memcpy(copy, path, len);

    rci_api_register_teardown(rci_svg_cache_shutdown);

    RCI_SvgCacheEntry *e = &rci_svg_cache[rci_svg_cacheCount++];
    e->path = copy;
    e->hash = h;

    e->svg  = rci_svg_load_path(path, "rcSvg");
    return e->svg;
}

static void rci_svg_cache_shutdown(void) {
    for (int i = 0; i < rci_svg_cacheCount; i++) {
        rcUnloadSvg(&rci_svg_cache[i].svg);
        free(rci_svg_cache[i].path);
        rci_svg_cache[i].path = NULL;
        rci_svg_cache[i].hash = 0;
    }
    rci_svg_cacheCount = 0;
}

void rcSvg(const char *path, float size, RC_Color color) {

    if (!path || !*path || size <= 0.0f) {
        return;
    }
    const RC_Svg *svg = rci_svg_cache_get(path);
    if (!svg) {
        return;
    }

    if (color.a == 0.0f) {
        color = rcGetStylePtr()->text;
    }
    rcSvgHandle(svg, size, color);
}

#else

RC_Svg *rcLoadSvg(const char *path) {
    (void)path;
    rci_core_log(RC_LOG_WARNING, "rcLoadSvg: built with RC_NO_SVG - SVG loading is compiled out");
    return NULL;
}

RC_Svg *rcLoadSvgFromMemory(const char *bytes, int len) {
    (void)bytes; (void)len;
    rci_core_log(RC_LOG_WARNING,
                 "rcLoadSvgFromMemory: built with RC_NO_SVG - SVG loading is compiled out");
    return NULL;
}

void rcUnloadSvg(RC_Svg **svg) {
    if (svg) {
        *svg = NULL;
    }
}

void rcSvgHandle(const RC_Svg *svg, float size, RC_Color color) {
    (void)svg; (void)size; (void)color;
}

void rcSvg(const char *path, float size, RC_Color color) {
    (void)size; (void)color;

    RCI_LOG_WARN_ONCE("rcSvg: built with RC_NO_SVG - '%s' is not drawn",
                      path ? path : "(null)");
}

