static inline double rci_input_fixed_dt_env(void) {
    const char *fdt = rci_env_get("RAYCLAY_FIXED_DT");
    if (!fdt)
        return 0.0;

    char *end;
    double v = strtod(fdt, &end);
    if (end == fdt)
        return 0.0;
    while (*end == ' ' || *end == '\t' || *end == '\r' || *end == '\n')
        end++;
    if (*end != '\0')
        return 0.0;
    return (v >= (double)FLT_MIN && v < 10.0) ? v : 0.0;
}

