#ifndef RC_TOUCH_SCROLL_H
#define RC_TOUCH_SCROLL_H

#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define RCI_TOUCH_SCROLL_SLOP 8.0

#define RCI_TOUCH_FLING_TAU     0.05
#define RCI_TOUCH_FLING_DECAY   0.95
#define RCI_TOUCH_FLING_STOP    8.0
#define RCI_TOUCH_FLING_HOLD    0.08
#define RCI_TOUCH_FLING_MAX  8000.0
#define RCI_TOUCH_FLING_DT_MAX  0.25

#define RCI_TOUCH_LONGPRESS_S 0.5

typedef struct RCI_TouchScroll {
    double start_x, start_y, last_x, last_y;
    double zoom;
    uint32_t x_id, y_id;
    bool active, dragging, rejected, consumed;
    bool has_x, has_y, use_x, use_y;

    double vel_x, vel_y;
    double sample_t;
    bool flinging;
} RCI_TouchScroll;

typedef struct RCI_TouchScrollDelta {
    double x, y;
    bool suppress;
} RCI_TouchScrollDelta;

static inline void rci_touch_scroll_begin(RCI_TouchScroll *s, double x, double y,
                                         double zoom) {
    *s = (RCI_TouchScroll){0};
    if (!isfinite(x) || !isfinite(y) || !isfinite(zoom) || zoom <= 0)
        return;
    s->active = true;
    s->start_x = s->last_x = x;
    s->start_y = s->last_y = y;
    s->zoom = zoom;
}

static inline RCI_TouchScrollDelta rci_touch_scroll_move(RCI_TouchScroll *s,
                                                        double x, double y,
                                                        double zoom, bool reserved) {
    RCI_TouchScrollDelta delta = {0};
    double dx, dy;

    if (!s->active || s->rejected)
        return delta;
    if (!isfinite(x) || !isfinite(y) || zoom != s->zoom) {
        delta.suppress = true;
        s->active = false;
        s->dragging = false;
        return delta;
    }
    if (!s->dragging && reserved) {
        s->rejected = true;
        return delta;
    }
    dx = x - s->start_x;
    dy = y - s->start_y;
    if (!s->dragging) {
        bool x_ready = s->has_x && fabs(dx) > RCI_TOUCH_SCROLL_SLOP;
        bool y_ready = s->has_y && fabs(dy) > RCI_TOUCH_SCROLL_SLOP;

        if (!x_ready && !y_ready)
            return delta;

        if (s->has_x && s->has_y && s->x_id == s->y_id) {
            s->use_x = s->use_y = true;
        } else if (x_ready && (!y_ready || fabs(dx) > fabs(dy))) {
            s->use_x = true;
        } else {
            s->use_y = true;
        }
        s->dragging = true;
        s->consumed = true;
    }
    delta.x = s->use_x ? (x - s->last_x) / zoom : 0;
    delta.y = s->use_y ? (y - s->last_y) / zoom : 0;
    delta.suppress = true;
    s->last_x = x;
    s->last_y = y;
    return delta;
}

static inline void rci_touch_scroll_track(RCI_TouchScroll *s, double x, double y,
                                          double now) {
    double dt, alpha;

    if (!s->active || !s->dragging)
        return;
    if (!isfinite(x) || !isfinite(y) || !isfinite(now))
        return;

    if (s->sample_t <= 0.0) {
        s->sample_t = now;
        return;
    }
    dt = now - s->sample_t;

    if (!(dt > 0.0) || dt > RCI_TOUCH_FLING_DT_MAX) {
        s->sample_t = now;
        return;
    }
    alpha = 1.0 - exp(-dt / RCI_TOUCH_FLING_TAU);
    s->vel_x += ((x - s->last_x) / dt - s->vel_x) * alpha;
    s->vel_y += ((y - s->last_y) / dt - s->vel_y) * alpha;
    s->sample_t = now;
}

static inline bool rci_touch_scroll_release(RCI_TouchScroll *s, double now) {
    double speed;

    s->flinging = false;
    if (!s->dragging || s->sample_t <= 0.0 || !isfinite(now))
        return false;

    if (now - s->sample_t > RCI_TOUCH_FLING_HOLD)
        return false;

    if (!s->use_x) s->vel_x = 0.0;
    if (!s->use_y) s->vel_y = 0.0;
    if (!isfinite(s->vel_x) || !isfinite(s->vel_y)) {
        s->vel_x = s->vel_y = 0.0;
        return false;
    }
    if (s->vel_x >  RCI_TOUCH_FLING_MAX) s->vel_x =  RCI_TOUCH_FLING_MAX;
    if (s->vel_x < -RCI_TOUCH_FLING_MAX) s->vel_x = -RCI_TOUCH_FLING_MAX;
    if (s->vel_y >  RCI_TOUCH_FLING_MAX) s->vel_y =  RCI_TOUCH_FLING_MAX;
    if (s->vel_y < -RCI_TOUCH_FLING_MAX) s->vel_y = -RCI_TOUCH_FLING_MAX;
    speed = sqrt(s->vel_x * s->vel_x + s->vel_y * s->vel_y);
    if (speed < RCI_TOUCH_FLING_STOP) {
        s->vel_x = s->vel_y = 0.0;
        return false;
    }
    s->flinging = true;
    return true;
}

static inline RCI_TouchScrollDelta rci_touch_scroll_fling_step(RCI_TouchScroll *s,
                                                               double dt) {
    RCI_TouchScrollDelta delta = {0};

    if (!s->flinging)
        return delta;
    if (!isfinite(dt) || dt <= 0.0 || !(s->zoom > 0.0)) {
        s->flinging = false;
        s->vel_x = s->vel_y = 0.0;
        return delta;
    }

    if (dt > RCI_TOUCH_FLING_DT_MAX)
        dt = RCI_TOUCH_FLING_DT_MAX;
    delta.x = s->use_x ? s->vel_x * dt / s->zoom : 0.0;
    delta.y = s->use_y ? s->vel_y * dt / s->zoom : 0.0;
    s->vel_x *= pow(RCI_TOUCH_FLING_DECAY, dt * 60.0);
    s->vel_y *= pow(RCI_TOUCH_FLING_DECAY, dt * 60.0);
    if (sqrt(s->vel_x * s->vel_x + s->vel_y * s->vel_y) < RCI_TOUCH_FLING_STOP) {
        s->flinging = false;
        s->vel_x = s->vel_y = 0.0;
    }
    return delta;
}

#endif

