struct RCI_TexteditContext {
    RCI_TexteditInputReg inputs[RCI_MAX_INPUTS];
    STB_TexteditState edit;
    double blinkT0;
    RC_ClipboardToken pasteToken;
    uint32_t focusedId;
    uint32_t pasteOwner;
    int inputCount;
    int pasteFrames;
    float scrollX;
    float scrollY;
    double lastClickT;
    float lastClickX;
    float lastClickY;
    uint32_t lastClickId;
    int clickCount;

    uint32_t pressCount;
    uint32_t lastClickPress;

    bool focused;
    bool clickValid;
    int8_t lastDir;
    bool dirty;
    bool dragging;
    bool windowFocused;

    uint32_t tapId;
    float    tapX, tapY;
    bool     tapArmed;
    bool     tapMoved;
};

static RCI_TexteditContext rci_textedit_fallback = { .windowFocused = true };
static RCI_TexteditContext *rci_textedit_context = &rci_textedit_fallback;

bool rci_textedit_pointer_grabbed(void) {
    return rci_textedit_context->dragging;
}

static void rci_textedit_wipe(void *data, size_t size) {
    volatile unsigned char *bytes = data;
    while (size--)
        *bytes++ = 0;
}

RCI_TexteditContext *rci_textedit_context_create(void) {
    RCI_TexteditContext *context = calloc(1, sizeof(*context));
    if (context)
        context->windowFocused = true;
    return context;
}

RCI_TexteditContext *rci_textedit_context_bind(RCI_TexteditContext *context) {
    RCI_TexteditContext *previous = rci_textedit_context;
    rci_textedit_context = context ? context : &rci_textedit_fallback;
    return previous;
}

void rci_textedit_context_destroy(RCI_TexteditContext *context) {
    if (!context || context == &rci_textedit_fallback)
        return;
    if (context == rci_textedit_context)
        rci_textedit_context_bind(NULL);
    rci_textedit_wipe(context, sizeof(*context));
    free(context);
}

void rci_textedit_textinput_note_clip(uint32_t id, Clay_BoundingBox clip) {
    for (int i = 0; i < rci_textedit_context->inputCount; ++i) {
        if (rci_textedit_context->inputs[i].idHash == id) {
            rci_textedit_context->inputs[i].clip    = clip;
            rci_textedit_context->inputs[i].hasClip = true;
            return;
        }
    }
}

int rci_textedit_textinput_count(void) {
    return rci_textedit_context->inputCount;
}

#define RCI_EDIT_ASCII_LO 0x20
#define RCI_EDIT_ASCII_N  95

typedef struct {
    char   *buf;
    int     len;
    int     cap;
    uint16_t font;
    float   size;
    bool    password;
    bool    multiline;
    float   bullet;
    float   wrapW;
    int8_t             LastMoveDirectionLR;
    STB_TexteditState *Stb;

    uint64_t asciiSeen[2];
    float    ascii[RCI_EDIT_ASCII_N];
} RCI_EditStr;

#define IMSTB_TEXTEDIT_GETWIDTH_NEWLINE (-1.0f)

static int rci_textedit_edit_seq_len(const RCI_EditStr *o, int idx) {
    unsigned char c0 = (unsigned char)o->buf[idx];
    if (c0 < 0x80) return 1;
    if ((c0 & 0xC0u) == 0x80u) return 0;
    int n = (c0 >= 0xF0 && c0 <= 0xF4) ? 4 : (c0 >= 0xE0) ? 3 : 2;
    return (n > o->len - idx) ? 1 : n;
}

static int rci_textedit_edit_next_index(const RCI_EditStr *o, int idx) {
    int n;
    if (idx < 0) return 0;
    if (idx >= o->len) return o->len;
    n = rci_textedit_edit_seq_len(o, idx);

    return idx + (n > 0 ? n : 1);
}

static int rci_textedit_edit_prev_index(const RCI_EditStr *o, int idx) {
    if (idx <= 0) return 0;
    if (idx > o->len) idx = o->len;
    idx--;

    while (idx > 0 && ((unsigned char)o->buf[idx] & 0xC0u) == 0x80u)
        idx--;
    return idx;
}

static float rci_textedit_edit_advance(RCI_EditStr *o, int idx) {
    if (o->password) return o->bullet;
    char c = o->buf[idx];
    if (o->multiline && c == '\n') return IMSTB_TEXTEDIT_GETWIDTH_NEWLINE;

    unsigned int k = (unsigned int)(unsigned char)c - RCI_EDIT_ASCII_LO;
    if (k < RCI_EDIT_ASCII_N) {
        uint64_t bit = (uint64_t)1 << (k & 63u);
        if (o->asciiSeen[k >> 6] & bit) return o->ascii[k];
        float w = rci_font_measure(o->font, o->size, o->buf + idx, o->buf + idx + 1);
        o->ascii[k] = w;
        o->asciiSeen[k >> 6] |= bit;
        return w;
    }
    int n = rci_textedit_edit_seq_len(o, idx);
    if (n == 0) return 0.0f;
    return rci_font_measure(o->font, o->size, o->buf + idx, o->buf + idx + n);
}

static float rci_textedit_edit_run_width(const RCI_EditStr *o, int from, int to) {
    if (to <= from) return 0.0f;
    if (o->password) return (float)(to - from) * o->bullet;
    return rci_font_measure(o->font, o->size, o->buf + from, o->buf + to);
}

static void rci_textedit_edit_prebake(uint16_t font, float size, const char *s, size_t n) {
    size_t i = 0;
    while (i < n) {
        if ((unsigned char)s[i] < 0x80) { i++; continue; }
        size_t j = i + 1;
        while (j < n && (unsigned char)s[j] >= 0x80) j++;
        size_t look = (n - j) < 3 ? n : j + 3;
        (void)rci_font_measure(font, size, s + i, s + look);
        i = j;
    }
}

static int rci_textedit_edit_insert(RCI_EditStr *o, int idx, const char *chars, int n) {
    int avail = (o->cap - 1) - o->len;
    if (avail <= 0) return 0;
    if (n > avail) n = avail;

    if (idx < 0) idx = 0;
    if (idx > o->len) idx = o->len;
    memmove(o->buf + idx + n, o->buf + idx, (size_t)(o->len - idx));
    memcpy(o->buf + idx, chars, (size_t)n);
    o->len += n;
    o->buf[o->len] = '\0';
    rci_textedit_context->dirty = true;
    return n;
}

static void rci_textedit_edit_delete(RCI_EditStr *o, int idx, int n) {

    if (idx < 0) idx = 0;
    if (idx > o->len) idx = o->len;
    if (n > o->len - idx) n = o->len - idx;
    if (n <= 0) return;
    memmove(o->buf + idx, o->buf + idx + n, (size_t)(o->len - idx - n));
    o->len -= n;
    o->buf[o->len] = '\0';
    rci_textedit_context->dirty = true;
}

static int rci_textedit_edit_row_span(RCI_EditStr *o, int start, float *out_w) {
    int   i        = start;
    float w        = 0.0f;
    int   break_at = -1;
    float break_w  = 0.0f;
    while (i < o->len) {
        char c = o->buf[i];
        if (c == '\n') { i++; break; }
        float cw = rci_textedit_edit_advance(o, i);
        if (o->wrapW > 0.0f && w + cw > o->wrapW && i > start) {
            if (break_at > start) { i = break_at; w = break_w; }
            break;
        }
        w += cw;
        i++;
        if (c == ' ') { break_at = i; break_w = w; }
    }
    if (out_w) *out_w = w;
    return i - start;
}

static int rci_textedit_edit_normalize_crlf(char *buf, int len) {
    int r = 0, w = 0;
    while (r < len) {
        if (buf[r] == '\r') {
            buf[w++] = '\n';
            r += (r + 1 < len && buf[r + 1] == '\n') ? 2 : 1;
        } else {
            buf[w++] = buf[r++];
        }
    }
    buf[w] = '\0';
    return w;
}

static float rci_textedit_edit_total_h(RCI_EditStr *o) {
    int i = 0, rows = 0;
    while (i < o->len) { i += rci_textedit_edit_row_span(o, i, NULL); rows++; }
    if (o->len == 0 || o->buf[o->len - 1] == '\n') rows++;
    return (float)rows * o->size;
}

static void rci_textedit_edit_layout(StbTexteditRow *r, RCI_EditStr *o, int start) {
    if (o->multiline) {
        float w;
        r->num_chars = rci_textedit_edit_row_span(o, start, &w);
        r->x0 = 0.0f;
        r->x1 = w;
    } else {
        r->x0 = 0.0f;
        r->x1 = rci_textedit_edit_run_width(o, start, o->len);
        r->num_chars = o->len - start;
    }
    r->baseline_y_delta = o->size;
    r->ymin = 0.0f;
    r->ymax = o->size;
}

#define IMSTB_TEXTEDIT_STRING                RCI_EditStr
#define STB_TEXTEDIT_STRINGLEN(o)            ((o)->len)

#define STB_TEXTEDIT_GETCHAR(o, i) \
    (((i) >= 0 && (i) < (o)->len) ? (o)->buf[(i)] : 0)
#define STB_TEXTEDIT_NEWLINE                 '\n'
#define IMSTB_TEXTEDIT_GETNEXTCHARINDEX(o, i) rci_textedit_edit_next_index((o), (i))
#define IMSTB_TEXTEDIT_GETPREVCHARINDEX(o, i) rci_textedit_edit_prev_index((o), (i))
#define STB_TEXTEDIT_GETWIDTH(o, n, i)       rci_textedit_edit_advance((o), (n) + (i))
#define STB_TEXTEDIT_LAYOUTROW(r, o, n)      rci_textedit_edit_layout((r), (o), (n))
#define STB_TEXTEDIT_DELETECHARS(o, i, n)    (rci_textedit_edit_delete((o), (i), (n)), 1)
#define STB_TEXTEDIT_INSERTCHARS(o, i, c, n) rci_textedit_edit_insert((o), (i), (c), (n))
#define STB_TEXTEDIT_IS_SPACE(ch)            ((ch) == ' ' || (ch) == '\t' || \
                                              (ch) == '\n' || (ch) == '\r')
#define STB_TEXTEDIT_K_SHIFT     0x400000
#define STB_TEXTEDIT_K_LEFT      0x200000
#define STB_TEXTEDIT_K_RIGHT     0x200001
#define STB_TEXTEDIT_K_UP        0x200002
#define STB_TEXTEDIT_K_DOWN      0x200003
#define STB_TEXTEDIT_K_LINESTART 0x200004
#define STB_TEXTEDIT_K_LINEEND   0x200005
#define STB_TEXTEDIT_K_TEXTSTART 0x200006
#define STB_TEXTEDIT_K_TEXTEND   0x200007
#define STB_TEXTEDIT_K_DELETE    0x200008
#define STB_TEXTEDIT_K_BACKSPACE 0x200009
#define STB_TEXTEDIT_K_UNDO      0x20000A
#define STB_TEXTEDIT_K_REDO      0x20000B
#define STB_TEXTEDIT_K_WORDLEFT  0x20000C
#define STB_TEXTEDIT_K_WORDRIGHT 0x20000D
#define STB_TEXTEDIT_K_PGUP      0x20000E
#define STB_TEXTEDIT_K_PGDOWN    0x20000F

static int rci_textedit_edit_move_rowstart(RCI_EditStr *o, STB_TexteditState *st, int cursor);
static int rci_textedit_edit_move_rowend(RCI_EditStr *o, STB_TexteditState *st, int cursor);
#define STB_TEXTEDIT_MOVELINESTART rci_textedit_edit_move_rowstart
#define STB_TEXTEDIT_MOVELINEEND   rci_textedit_edit_move_rowend
#define IMSTB_TEXTEDIT_IMPLEMENTATION

