static GLFWwindow *rci_window_glfw_gw(RCI_Window *w) { return (GLFWwindow *)w; }

typedef struct RCI_WindowGlfwRecord {
    struct RCI_WindowGlfwRecord *next;
    GLFWwindow *window;
    void *user;
    void (*refresh)(RCI_Window *);
    RCI_WindowInputCallbacks input;
    RCI_WindowCursor cursor_shape;
    bool             cursor_shape_set;
    RCI_Window      *owner;
    char            *clipboard;
} RCI_WindowGlfwRecord;

static RCI_WindowGlfwRecord *rci_window_glfw_records;

static RCI_WindowGlfwRecord *rci_window_glfw_record(GLFWwindow *gw) {
    return gw ? (RCI_WindowGlfwRecord *)glfwGetWindowUserPointer(gw) : NULL;
}

#ifndef __EMSCRIPTEN__

static GLFWwindow *rci_window_glfw_live(RCI_Window *w) {
    for (RCI_WindowGlfwRecord *s = rci_window_glfw_records; w && s; s = s->next)
        if (s->window == (GLFWwindow *)w)
            return s->window;
    return NULL;
}
#endif

