#endif
static void rci_window_glfw_events_pumped(void) {
#ifndef __EMSCRIPTEN__
    rci_window_glfw_letters_fresh = false;
#endif

    for (RCI_WindowGlfwRecord *rec = rci_window_glfw_records; rec; rec = rec->next)
        rci_window_glfw_clipboard_clear(rec);
}

