void rci_window_set_cursor(RCI_Window *w, RCI_WindowCursor shape) {

    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(rci_window_glfw_gw(w));
    if (rec) {
        if (rec->cursor_shape_set && shape == rec->cursor_shape)
            return;
        rec->cursor_shape     = shape;
        rec->cursor_shape_set = true;
    }
#ifdef __EMSCRIPTEN__
    const char *css;
    switch (shape) {
    case RCI_WINDOW_CURSOR_POINTER:     css = "pointer";     break;
    case RCI_WINDOW_CURSOR_IBEAM:       css = "text";        break;
    case RCI_WINDOW_CURSOR_GRAB:        css = "grab";        break;
    case RCI_WINDOW_CURSOR_GRABBING:    css = "grabbing";    break;
    case RCI_WINDOW_CURSOR_NOT_ALLOWED: css = "not-allowed"; break;
    case RCI_WINDOW_CURSOR_RESIZE_EW:   css = "ew-resize";   break;
    case RCI_WINDOW_CURSOR_RESIZE_NS:   css = "ns-resize";   break;
    case RCI_WINDOW_CURSOR_RESIZE_NESW: css = "nesw-resize"; break;
    case RCI_WINDOW_CURSOR_RESIZE_NWSE: css = "nwse-resize"; break;
    default:                           css = "default";     break;
    }
    rci_window_glfw_web_set_css_cursor(css);
#else
    if (!rci_window_glfw_cursors_made) {
        rci_window_glfw_cursor_ew      = glfwCreateStandardCursor(GLFW_RESIZE_EW_CURSOR);
        rci_window_glfw_cursor_ns      = glfwCreateStandardCursor(GLFW_RESIZE_NS_CURSOR);
        rci_window_glfw_cursor_nesw    = glfwCreateStandardCursor(GLFW_RESIZE_NESW_CURSOR);
        rci_window_glfw_cursor_nwse    = glfwCreateStandardCursor(GLFW_RESIZE_NWSE_CURSOR);
        rci_window_glfw_cursor_pointer = glfwCreateStandardCursor(GLFW_POINTING_HAND_CURSOR);
        rci_window_glfw_cursor_ibeam   = glfwCreateStandardCursor(GLFW_IBEAM_CURSOR);
        rci_window_glfw_cursor_move    = glfwCreateStandardCursor(GLFW_RESIZE_ALL_CURSOR);
        rci_window_glfw_cursor_no      = glfwCreateStandardCursor(GLFW_NOT_ALLOWED_CURSOR);
        rci_window_glfw_cursors_made   = true;
    }
    GLFWcursor *c;
    switch (shape) {
    case RCI_WINDOW_CURSOR_RESIZE_EW:   c = rci_window_glfw_cursor_ew;      break;
    case RCI_WINDOW_CURSOR_RESIZE_NS:   c = rci_window_glfw_cursor_ns;      break;
    case RCI_WINDOW_CURSOR_RESIZE_NESW: c = rci_window_glfw_cursor_nesw;    break;
    case RCI_WINDOW_CURSOR_RESIZE_NWSE: c = rci_window_glfw_cursor_nwse;    break;
    case RCI_WINDOW_CURSOR_POINTER:     c = rci_window_glfw_cursor_pointer; break;
    case RCI_WINDOW_CURSOR_IBEAM:       c = rci_window_glfw_cursor_ibeam;   break;
    case RCI_WINDOW_CURSOR_GRAB:
    case RCI_WINDOW_CURSOR_GRABBING:    c = rci_window_glfw_cursor_move;    break;
    case RCI_WINDOW_CURSOR_NOT_ALLOWED: c = rci_window_glfw_cursor_no;      break;
    default:                           c = NULL; break;
    }
    glfwSetCursor(rci_window_glfw_gw(w), c);
#endif
}

RCI_STATIC_ASSERT(RC_POINTER_LEFT   == GLFW_MOUSE_BUTTON_LEFT  &&
                  RC_POINTER_RIGHT  == GLFW_MOUSE_BUTTON_RIGHT &&
                  RC_POINTER_MIDDLE == GLFW_MOUSE_BUTTON_MIDDLE,
                  "RC_PointerButton must stay numbered like GLFW's mouse buttons");

RCI_STATIC_ASSERT(GLFW_KEY_LAST < RCI_WINDOW_KEY_CODE_LIMIT,
                  "GLFW key codes must fit under the seam's key-code ceiling");
RCI_STATIC_ASSERT(GLFW_KEY_UNKNOWN == RCI_WINDOW_KEY_CODE_NONE,
                  "the key trampoline hands GLFW_KEY_UNKNOWN through as the seam's no-code value");
RCI_STATIC_ASSERT(RCI_WINDOW_KEY_ACTION_RELEASE == GLFW_RELEASE &&
                  RCI_WINDOW_KEY_ACTION_PRESS   == GLFW_PRESS   &&
                  RCI_WINDOW_KEY_ACTION_REPEAT  == GLFW_REPEAT,
                  "the seam's key actions are handed GLFW's through unchanged");

static void rci_window_glfw_key_trampoline(GLFWwindow *gw, int key, int scancode, int action, int mods) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    (void)scancode; (void)mods;
    if (rec && rec->input.key)
        rec->input.key((RCI_Window *)gw, key, (RCI_WindowKeyAction)action);
}
static void rci_window_glfw_char_trampoline(GLFWwindow *gw, unsigned int codepoint) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.character)
        rec->input.character((RCI_Window *)gw, codepoint);
}
static void rci_window_glfw_mouse_button_trampoline(GLFWwindow *gw, int button, int action, int mods) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    (void)mods;

    if (button < GLFW_MOUSE_BUTTON_LEFT || button > GLFW_MOUSE_BUTTON_MIDDLE)
        return;
    if (rec && rec->input.mouse_button)
        rec->input.mouse_button((RCI_Window *)gw, (RC_PointerButton)button, action == GLFW_PRESS);
}
static void rci_window_glfw_scroll_trampoline(GLFWwindow *gw, double dx, double dy) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.scroll)
        rec->input.scroll((RCI_Window *)gw, dx, dy);
}
static void rci_window_glfw_cursor_pos_trampoline(GLFWwindow *gw, double x, double y) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.cursor_pos)
        rec->input.cursor_pos((RCI_Window *)gw, x, y);
}
static void rci_window_glfw_cursor_enter_trampoline(GLFWwindow *gw, int entered) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (rec && rec->input.cursor_enter)
        rec->input.cursor_enter((RCI_Window *)gw, entered == GLFW_TRUE);
}

void rci_window_set_input_callbacks(RCI_Window *w, const RCI_WindowInputCallbacks *cbs) {
    GLFWwindow *gw = rci_window_glfw_gw(w);
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(gw);
    if (!rec) return;
    if (cbs) rec->input = *cbs;
    else     memset(&rec->input, 0, sizeof rec->input);

    glfwSetKeyCallback        (gw, rec->input.key          ? rci_window_glfw_key_trampoline          : NULL);
    glfwSetCharCallback       (gw, rec->input.character    ? rci_window_glfw_char_trampoline         : NULL);
    glfwSetMouseButtonCallback(gw, rec->input.mouse_button ? rci_window_glfw_mouse_button_trampoline : NULL);
    glfwSetScrollCallback     (gw, rec->input.scroll       ? rci_window_glfw_scroll_trampoline       : NULL);
    glfwSetCursorPosCallback  (gw, rec->input.cursor_pos   ? rci_window_glfw_cursor_pos_trampoline   : NULL);
    glfwSetCursorEnterCallback(gw, rec->input.cursor_enter ? rci_window_glfw_cursor_enter_trampoline : NULL);
}

void *rci_window_input_user(RCI_Window *w) {
    RCI_WindowGlfwRecord *rec = rci_window_glfw_record(rci_window_glfw_gw(w));

    return rec ? rec->input.user : NULL;
}

