static uint64_t rci_app_phase_ns[RCI_PHASE_COUNT];

static const char *const rci_app_phase_name[] = {
    "entry", "sysinit", "window", "gfx", "font_init", "font_bake", "clay",
    "first_present"
};
RCI_STATIC_ASSERT(sizeof(rci_app_phase_name) / sizeof(*rci_app_phase_name) == RCI_PHASE_COUNT,
               "add the phase's name in the same edit as its enumerator");

void rci_app_phase_mark(RCI_Phase p)
{
    struct timespec ts;
    if (p < 0 || p >= RCI_PHASE_COUNT)
        return;

    if (rci_app_phase_ns[p] != 0)
        return;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return;
    rci_app_phase_ns[p] = (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}

void rci_app_phase_report(void)
{
    uint64_t prev = 0;
    int i;
    for (i = 0; i < RCI_PHASE_COUNT; i++) {
        if (rci_app_phase_ns[i] == 0) {
            fprintf(stderr, "RC_PHASE\t%s\tabsent\tabsent\n", rci_app_phase_name[i]);
            continue;
        }
        fprintf(stderr, "RC_PHASE\t%s\t%llu\t%llu\n", rci_app_phase_name[i],
                (unsigned long long)(rci_app_phase_ns[i] - rci_app_phase_ns[0]),
                (unsigned long long)(prev ? rci_app_phase_ns[i] - prev : 0));
        prev = rci_app_phase_ns[i];
    }
}
#endif

