enum { RCI_ICON_SOURCES_MAX = 8 };
static RCI_WindowIconSource rci_app_icon_sources[RCI_ICON_SOURCES_MAX];
static unsigned char        *rci_app_icon_owned = NULL;

static void rci_app_release_app_icon(void) {
    rci_image_free_file_bytes(rci_app_icon_owned);
    rci_app_icon_owned = NULL;
    rci_app_icon_bytes = NULL;
    rci_app_icon_length = 0;
    rci_app_icon_path = NULL;
    memset(rci_app_icon_sources, 0, sizeof rci_app_icon_sources);
}

static int rci_app_prepare_app_icon(void) {
    RCI_WindowIconSource *sources = rci_app_icon_sources;
    unsigned char *owned = NULL;
    int n = 0;

    if (rci_app_icon_bytes && rci_app_icon_length > 0) {
        sources[0].bytes  = rci_app_icon_bytes;
        sources[0].length = rci_app_icon_length;
        n = 1;
    } else if (rci_app_icon_path) {
        int len = 0;
        owned = rci_image_read_file_bytes(rci_app_icon_path, &len);
        if (owned) {
            sources[0].bytes  = owned;
            sources[0].length = len;
            n = 1;
        }

    }
#ifndef RC_NO_DEFAULT_APP_ICON
    if (n == 0) {
        int count = 0;
        const RCI_AppIconPng *set = rci_app_appicon_png_set(&count);
        for (int i = 0; i < count && n < RCI_ICON_SOURCES_MAX; i++) {
            sources[n].bytes  = set[i].data;
            sources[n].length = (int)set[i].len;
            n++;
        }
    }
#endif
    rci_app_icon_owned = owned;
    return n;
}

static RCI_WindowDesc rci_app_window_desc(void *owner, int width, int height,
                                        const char *title) {

    bool decorated = true;
#if !defined(__APPLE__)
    if (rci_app_chrome->native_frame) decorated = false;
#endif

    RCI_WindowDesc desc = {
        .width     = width  > 0 ? width  : 1024,
        .height    = height > 0 ? height : 768,
        .title     = title ? title : "RayClay",
        .gl_major  = 3,
        .gl_minor  = 3,

        .samples   = rci_gfx_msaa_samples(),
        .resizable = true,
        .decorated = decorated,
        .user      = owner,
    };
#if RCI_PLATFORM_MOBILE
    desc.gl_minor = 0;
#endif

    float chipW = rci_app_chrome->chip_width > 0.0f ? rci_app_chrome->chip_width : RCI_CHIP_W;
    int floorW  = rci_app_chrome->chips > 0
                     ? RCI_CONTROLS_MIN_W_NW(rci_app_chrome->chips, chipW)
                     : RCI_CONTROLS_MIN_W;
    int floorH = rci_app_chrome->caption_height > 0 ? rci_app_chrome->caption_height : (int)RCI_TITLEBAR_H;

    int minW = rci_app_chrome->min_width > 0 ? rci_app_chrome->min_width : floorW;
    int minH = rci_app_chrome->min_height > 0 ? rci_app_chrome->min_height : floorH;

    if (rci_app_chrome->native_frame && !rci_app_chrome->allow_controls_clip && rci_app_chrome->chips > 0) {
        if (rci_app_chrome->min_width > 0 && minW < floorW) {
            rci_core_log(RC_LOG_WARNING, "RC_AppOptions.minWidth %d raised to %d: the "
                    "window controls would not fit. Set titlebar.allowControlsClip "
                    "to keep your value.", minW, floorW);
            minW = floorW;
        }

        if (rci_app_chrome->min_height > 0 && minH < floorH) {
            rci_core_log(RC_LOG_WARNING, "RC_AppOptions.minHeight %d raised to %d: the "
                    "title bar would not fit. Set titlebar.allowControlsClip to "
                    "keep your value.", minH, floorH);
            minH = floorH;
        }
    }
    rci_app_chrome->min_width = rci_app_chrome->min_height = 0;
    desc.min_width  = minW;
    desc.min_height = minH;
    if (desc.width  < minW) desc.width  = minW;
    if (desc.height < minH) desc.height = minH;
    return desc;
}

static bool rci_app_open_window(void *owner, int width, int height, const char *title) {
    if (rci_app_window) {
        rci_core_log(RC_LOG_WARNING, "rcInitWindow: a window already exists");
        return false;
    }

#if RCI_WINDOW_HAS_OWN_DECORATIONS_HINT

    void rci_window_hint_own_decorations(bool own);

    rci_window_hint_own_decorations(rci_app_chrome->native_frame);
#endif
    if (!rci_window_system_init()) {
        rci_core_log(RC_LOG_ERROR, "rcInitWindow: window-system init failed");
        return false;
    }

    RCI_PHASE_MARK(RCI_PHASE_SYSINIT);

    RCI_WindowDesc desc = rci_app_window_desc(owner, width, height, title);
    desc.icons     = rci_app_icon_sources;
    desc.icon_count = rci_app_prepare_app_icon();
    desc.orientation = rci_app_chrome->orientation;
    rci_app_window = rci_window_create(&desc);
    rci_app_release_app_icon();
    if (rci_app_window) {
        rci_app_torn_down = false;
    }
    if (!rci_app_window) {
        rci_core_log(RC_LOG_ERROR, "rcInitWindow: window creation failed");
        rci_window_system_shutdown();
        return false;
    }

    rci_window_make_current(rci_app_window);
    rci_window_swap_interval(1);
    RCI_PHASE_MARK(RCI_PHASE_WINDOW);

    rci_gfx_init(rci_window_gl_proc);
    if (!rci_gfx_ready()) {

        rci_core_log(RC_LOG_ERROR, "rcInitWindow: render backend init failed");
        rci_release_deferred_storage();
    rci_gfx_shutdown();
        rci_window_destroy(rci_app_window);
        rci_app_window = NULL;
        rci_window_system_shutdown();
        return false;
    }

#if RCI_PLATFORM_MOBILE

    rci_gfx_set_swapchain_framebuffer(rci_window_drawable_framebuffer(rci_app_window));
#endif
    RCI_PHASE_MARK(RCI_PHASE_GFX);
    rci_input_init(rci_app_window);
    rci_font_init();
    RCI_PHASE_MARK(RCI_PHASE_FONT_INIT);

#if !defined(__EMSCRIPTEN__) && !RCI_PLATFORM_MOBILE

    if (rci_app_chrome->native_frame) {
        if (!rci_titlebar_attach((RCI_TitlebarWindow *)rci_app_window, rci_app_chrome->caption_height,
                                 RCI_CAPTION_HIT, owner))
            rci_core_log(RC_LOG_WARNING,
                    "rcInitWindow: title bar attach failed; the window may be "
                    "undraggable/unresizable");
#ifndef RC_NO_APP_RUNNER

        if (rci_window_platform() == RCI_WINDOW_PLATFORM_WAYLAND &&
            !rci_titlebar_can_resize() &&
            !rci_window_set_hit_test(rci_app_window, rci_app_host_hit_test, owner))
            rci_core_log(RC_LOG_WARNING,
                    "rcInitWindow: no native move/resize on this host; the window "
                    "may be undraggable/unresizable");
#endif
    }
#endif
    return true;
}

void rcInitWindow(int width, int height, const char *title) {
    if (!rci_app_window)
        rci_app_chrome = &rci_app_chrome_fallback;
    (void)rci_app_open_window(NULL, width, height, title);
}

void rcCloseWindow(void) {
#ifndef RC_NO_APP_RUNNER
    if (!rci_app_prepare_close())
        return;
#endif

    if (rci_app_pump_depth > 0) {
        rci_app_close_deferred = rci_app_window;
        return;
    }

    if (rci_app_torn_down) {
        return;
    }
    rci_app_torn_down = true;

    if (rci_app_window) {
        rci_window_make_current(rci_app_window);
        rci_window_prepare_teardown();
    }
    rci_font_shutdown();
    rci_text_shutdown();
    rci_textedit_textinput_shutdown();
    rci_api_clipboard_shutdown();
    rci_api_icon_pool_shutdown();
    rci_api_run_teardowns();
    rci_widgets_shutdown();
    rci_intent_shutdown();
    rci_api_scroll_consumed_set(false);
    rci_input_shutdown();
    rci_release_deferred_storage();
    rci_gfx_shutdown();

    if (rci_app_window) {

        rci_window_set_refresh_callback(rci_app_window, NULL);
        rci_titlebar_detach();
        rci_window_destroy(rci_app_window);
        rci_app_window = NULL;

        rci_app_close_deferred = NULL;
    }

    rci_app_chrome->native_frame   = false;
    rci_app_chrome->caption_height      = 0;
    rci_app_chrome->allow_controls_clip = false;
    rci_app_chrome->chips     = 0;
    rci_app_chrome->chip_width = 0.0f;

    rci_window_set_managed_loop(false);
    rci_window_system_shutdown();
#ifndef RC_NO_APP_RUNNER
    rci_app_note_closed();
#endif
}

Clay_Dimensions rcGetWindowDimensions(void) {
    if (rci_app_window) {
        int w = 0, h = 0;
        rci_window_get_size(rci_app_window, &w, &h);
        if (w > 0 && h > 0)
            return (Clay_Dimensions){ (float)w, (float)h };
    }
    return (Clay_Dimensions){ 1.0f, 1.0f };
}

float rcGetContentScale(void) {
    if (rci_app_window) {
        int fbw = 0, fbh = 0, lw = 0, lh = 0;
        rci_window_get_fb_size(rci_app_window, &fbw, &fbh);
        rci_window_get_size(rci_app_window, &lw, &lh);
        if (lw > 0 && fbw > 0)
            return (float)fbw / (float)lw;
    }
    return 1.0f;
}

static Clay_Dimensions rci_app_viewport_dimensions(float z) {
    Clay_Dimensions d = rcGetWindowDimensions();
    if (z <= 0.0f) z = 1.0f;

    d.width  = rci_app_zoom_axis_floor(d.width,  z);
    d.height = rci_app_zoom_axis_floor(d.height, z);
    if (d.width  < 1.0f) d.width  = 1.0f;
    if (d.height < 1.0f) d.height = 1.0f;
    return d;
}

static Clay_Dimensions rci_app_render_dimensions(void) {
    return rci_app_viewport_dimensions(rci_api_zoom_get());
}

static Clay_Dimensions rci_app_layout_dimensions(void) {
    if (!rci_api_zoom_optical_get()) {

        Clay_Dimensions r = rci_app_render_dimensions();

        if (r.width  < 1.0f) r.width  = 1.0f;
        if (r.height < 1.0f) r.height = 1.0f;
        return r;
    }

    Clay_Dimensions win  = rcGetWindowDimensions();
    Clay_Dimensions view = rci_app_viewport_dimensions(rci_api_zoom_get());
    Clay_Dimensions d    = {0};
    d.width  = (float)(int)(win.width  > view.width  ? win.width  : view.width);
    d.height = (float)(int)(win.height > view.height ? win.height : view.height);
    if (d.width  < 1.0f) d.width  = 1.0f;
    if (d.height < 1.0f) d.height = 1.0f;
    return d;
}

RC_Viewport rcViewport(void) {
    Clay_Dimensions layout = rci_app_layout_dimensions();
    Clay_Dimensions win    = rcGetWindowDimensions();
    RC_Insets       safe   = rcGetSafeAreaInsets();

    RC_Viewport     v      = {0};

    v.width  = layout.width;
    v.height = layout.height;

    v.safe = rci_viewport_safe_to_layout(safe, layout.width, layout.height,
                                         win.width, win.height);
    v.breakpoint    = rci_viewport_breakpoint(v.width);
    v.coarsePointer = rcPointerIsCoarse();

    v.keyboard = rci_viewport_safe_to_layout(rcGetKeyboardInsets(), layout.width,
                                             layout.height, win.width, win.height);
    return v;
}

void rcSyncLayoutDimensions(void) {
    if (!Clay_GetCurrentContext()) return;
    Clay_SetLayoutDimensions(rci_app_layout_dimensions());
}

