struct RCI_TitlebarContext {
    RCI_TitlebarWindow *window;
    int ntb_active;
    RCI_TitlebarCaptionHitCallback hit_fn;
    void *hit_ud;
    int caption_h;
};

static RCI_TitlebarContext rci_titlebar_fallback;
static RCI_TitlebarContext *rci_titlebar_current = &rci_titlebar_fallback;

static void rci_titlebar_context_clear(RCI_TitlebarContext *context) {
    if (context->ntb_active)
        ntb_uninstall(rci_titlebar_native(context->window));
    *context = (RCI_TitlebarContext){0};
}

RCI_TitlebarContext *rci_titlebar_context_create(void) {
    return calloc(1, sizeof(RCI_TitlebarContext));
}

RCI_TitlebarContext *rci_titlebar_context_bind(RCI_TitlebarContext *context) {
    RCI_TitlebarContext *previous = rci_titlebar_current;

    rci_titlebar_current = context ? context : &rci_titlebar_fallback;
    return previous;
}

void rci_titlebar_context_destroy(RCI_TitlebarContext *context) {
    if (!context || context == &rci_titlebar_fallback)
        return;
    rci_titlebar_context_clear(context);
    if (rci_titlebar_current == context)
        rci_titlebar_current = &rci_titlebar_fallback;
    free(context);
}

static ntb_hit_result rci_titlebar_ntb_hit_adapter(void *ud, int x, int y) {
    RCI_TitlebarContext *context = ud;

    if (!context || !context->hit_fn) return NTB_HIT_DRAG;
    switch (context->hit_fn(context->hit_ud, x, y)) {
        case RCI_CAPTION_CLIENT:   return NTB_HIT_CLIENT;
        case RCI_CAPTION_MAXIMIZE: return NTB_HIT_MAXIMIZE;
        case RCI_CAPTION_DRAG:
        default:                  return NTB_HIT_DRAG;
    }
}

static int rci_titlebar_context_install(RCI_TitlebarContext *context) {
    context->ntb_active = ntb_install(
        rci_titlebar_native(context->window),
        (ntb_config){ .caption_height = context->caption_h,
                      .keep_shadow = 1,
                      .hittest = context->hit_fn ? rci_titlebar_ntb_hit_adapter : NULL,
                      .user_data = context });
    return context->ntb_active;
}

int rci_titlebar_attach(RCI_TitlebarWindow *win, int captionHeight,
                        RCI_TitlebarCaptionHitCallback hit, void *hitUserData) {
    RCI_TitlebarContext *context = rci_titlebar_current;
    int h = captionHeight > 0 ? captionHeight : 0;

    if (!win) return 0;
    if (context->ntb_active && context->window == win &&
        context->caption_h == h && context->hit_fn == hit &&
        context->hit_ud == hitUserData)
        return 1;
    if (context->window != win)
        rci_titlebar_context_clear(context);
    context->window = win;
    context->hit_fn = hit;
    context->hit_ud = hitUserData;
    context->caption_h = h;
#ifndef _WIN32

    if (context->ntb_active)
        return 1;
#endif
    return rci_titlebar_context_install(context);
}

void rci_titlebar_set_caption_height(int captionHeight) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    int h = captionHeight > 0 ? captionHeight : 0;

    if (!context->ntb_active) return;
    if (h == context->caption_h) return;
    context->caption_h = h;

#ifdef _WIN32

    rci_titlebar_context_install(context);
#endif
}

void rci_titlebar_detach(void) {
    rci_titlebar_context_clear(rci_titlebar_current);
}

int rci_titlebar_start_move(void) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    return context->ntb_active ? ntb_start_move(rci_titlebar_native(context->window)) : 0;
}

int rci_titlebar_start_resize(int edge) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    return context->ntb_active ? ntb_start_resize(rci_titlebar_native(context->window), (ntb_edge)edge) : 0;
}

int rci_titlebar_can_resize(void) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    return context->ntb_active ? (int)(ntb_capabilities(rci_titlebar_native(context->window)) & NTB_CAP_RESIZE) : 0;
}

void rci_titlebar_set_maximized(int on) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    if (context->ntb_active) ntb_set_maximized(rci_titlebar_native(context->window), on);
}

int rci_titlebar_is_maximized(void) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    return context->ntb_active ? ntb_is_maximized(rci_titlebar_native(context->window)) : 0;
}

int rci_titlebar_topmost_set(RCI_TitlebarWindow *win, int on) {
    if (!win) return 0;
    return ntb_set_topmost(rci_titlebar_native(win), on);
}

int rci_titlebar_topmost_get(RCI_TitlebarWindow *win) {
    if (!win) return 0;
    return ntb_is_topmost(rci_titlebar_native(win));
}

int rci_titlebar_topmost_supported(RCI_TitlebarWindow *win) {
    if (!win) return 0;
    return ntb_topmost_available(rci_titlebar_native(win)) != 0;
}

int rci_titlebar_verb_settled(void) {
#if defined(__APPLE__)
    RCI_TitlebarContext *context = rci_titlebar_current;

    return context->ntb_active ? ntb_maximize_settled(rci_titlebar_native(context->window)) : 1;
#else
    return 1;
#endif
}

int rci_titlebar_max_chip_hovered(void) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    return context->ntb_active ? ntb_max_button_hovered(rci_titlebar_native(context->window)) : 0;
}

int rci_titlebar_max_chip_pressed(void) {
    RCI_TitlebarContext *context = rci_titlebar_current;

    return context->ntb_active ? ntb_max_button_pressed(rci_titlebar_native(context->window)) : 0;
}

#endif
#define RAYCLAY_SINGLE_H_IMPLEMENTED 1
#endif
#else
#if defined(RAYCLAY_IMPLEMENTATION) && !defined(RAYCLAY_SINGLE_H_IMPLEMENTED)
#error "RAYCLAY_IMPLEMENTATION must be defined before the FIRST include of rayclay.h in a translation unit"
#endif
